import {
  PageLabelInfoWithPosition,
  PageLabelVisibilityHandler,
  PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
} from '../types'

import { ContainersLayer } from './containers-layer'
import {
  PageLabelsRenderer,
  PageLabelRendererGetSpineItemViewOffset,
  PageLabelRendererPageLayoutParameters,
} from './page-labels-renderer'
import { VisibleRangeUpdate } from './types'
import { applyCssRulesToNonInteractiveElementStyle } from './utils'

export type PageLabelsViewConstructorParams = {
  getSpineItemViewOffset: PageLabelRendererGetSpineItemViewOffset
  pageLabelVisibilityHandler: PageLabelVisibilityHandler<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  >
}

const PageLabelsContainerStyleMain: Partial<CSSStyleDeclaration> = {
  position: 'absolute',
  boxSizing: 'border-box',
  height: '100%',
  width: '100%',
  margin: '0',
  padding: '0',
  border: 'none',
  willChange: 'transform',
}

function createPageLabelsOuterContainer(): HTMLElement {
  const pageLabelsContainer = document.createElement('div')
  const pageLabelsContainerStyle = pageLabelsContainer.style
  const pageLabelsContainerStyleUpdated: Partial<CSSStyleDeclaration> = {
    ...PageLabelsContainerStyleMain,
    height: '100%',
    width: '100%',
  }
  Object.assign(pageLabelsContainerStyle, pageLabelsContainerStyleUpdated)
  applyCssRulesToNonInteractiveElementStyle(pageLabelsContainerStyle)
  pageLabelsContainer.setAttribute('role', 'presentation')
  return pageLabelsContainer
}

export class PageLabelsView {
  private pageLabelsRenderer: PageLabelsRenderer

  private pageLabelsOuterContainer: HTMLElement

  private arePageLabelsVisible = false

  constructor(parameters: PageLabelsViewConstructorParams) {
    this.initializePageLabelsRenderer(parameters)
  }

  public attachToContainersLayer(containersLayer: ContainersLayer): void {
    containersLayer.addContainer(this.pageLabelsOuterContainer)
  }

  public renderPageLabels(
    pageLabelsInfo: PageLabelInfoWithPosition[],
    layoutParameters: PageLabelRendererPageLayoutParameters,
  ): void {
    const pageLabelsRenderer = this.pageLabelsRenderer

    pageLabelsRenderer.updatePageLabelsInfo(pageLabelsInfo)
    this.updateLayoutParametersAndRecalculateVisibilityOfPageLabels(
      layoutParameters,
    )
    this.render()
  }

  public updateLayoutParameters(
    layoutParameters: PageLabelRendererPageLayoutParameters,
  ): void {
    this.updateLayoutParametersAndRecalculateVisibilityOfPageLabels(
      layoutParameters,
    )
    this.render()
  }

  public handleVisibleRangeUpdate(
    visibleRangeUpdate: VisibleRangeUpdate,
  ): void {
    this.pageLabelsRenderer.handleVisibleRangeUpdate(visibleRangeUpdate)
    this.pageLabelsRenderer.recalculateVisibility()
    this.render()
  }

  public handlePageLabelsVisibilityChange(arePageLabelsVisible: boolean): void {
    const currentPageLabelsVisibility = this.arePageLabelsVisible

    this.arePageLabelsVisible = arePageLabelsVisible
    if (!arePageLabelsVisible) {
      this.removeAllPageLabelsFromScreen()
    } else if (currentPageLabelsVisibility !== arePageLabelsVisible) {
      this.render()
    }
  }

  protected initializePageLabelsRenderer(
    parameters: PageLabelsViewConstructorParams,
  ): void {
    const { getSpineItemViewOffset, pageLabelVisibilityHandler } = parameters
    const pageLabelsContainer = createPageLabelsOuterContainer()
    const pageLabelsRenderer = new PageLabelsRenderer({
      pageLabelsContainer,
      getSpineItemViewOffset,
      pageLabelVisibilityHandler,
    })

    pageLabelsContainer.id = 'flowpub-page-labels-container'
    this.pageLabelsRenderer = pageLabelsRenderer
    this.pageLabelsOuterContainer = pageLabelsContainer
  }

  protected removeAllPageLabelsFromScreen(): void {
    this.pageLabelsRenderer.removeVisiblePageLabels()
  }

  protected resetAndRerenderPageLabels(): void {
    this.removeAllPageLabelsFromScreen()
    this.render()
  }

  protected render(): void {
    if (!this.arePageLabelsVisible) {
      return
    }
    this.pageLabelsRenderer.renderPageLabels()
  }

  protected updateLayoutParametersAndRecalculateVisibilityOfPageLabels(
    layoutParameters: PageLabelRendererPageLayoutParameters,
  ): void {
    const pageLabelsRenderer = this.pageLabelsRenderer
    pageLabelsRenderer.updateLayoutParameters(layoutParameters)
    pageLabelsRenderer.recalculateVisibility()
  }
}
