import { ContentInjectionScriptFactory } from './types'

/**
 * An optional options, which will be taken into account.
 *
 * @export
 * @interface ContentInjectionScriptFactoryOptions
 */
export interface ContentInjectionScriptFactoryOptions {
  /**
   * Text of js script to inject in the iframe along with the main script.
   * The script will be put into <script> tag right after the <script> tag
   * with content injection listener script.
   *
   * @type {string}
   * @memberof ContentInjectionScriptFactoryOptions
   */
  jsScriptToAppend: string
}

export function contentInjectionScriptFactoryImpl(
  replaceContentMessageType: string,
  options?: Partial<ContentInjectionScriptFactoryOptions>,
): string {
  if (!replaceContentMessageType) {
    throw new Error('Message type should be defined')
  }
  const { jsScriptToAppend } = options ?? {}
  const additionalScript = !jsScriptToAppend
    ? ''
    : `<script>
        ${jsScriptToAppend}
      </script>`
  const htmlWithScript = `
        <html>
            <head>
                ${additionalScript}
                <script>
                    window.addEventListener("message", function(event) {
                        try {
                          const msg = event.data
                          if (msg.type === "${replaceContentMessageType.trim()}"  ) {
                              const htmlCode = msg.documentContent
                              const documentMimeType = msg.documentMIMEType || 'text/xml'
                              document.open(documentMimeType || 'text/xml', "replace")
                              document.write(htmlCode)
                              document.close();
                          }
                        } catch (err) {
                          console.error(err)
                          console.log(event.data)
                        }
                    }, false);
                </script>
            </head>
        </html>
    `
  return htmlWithScript
}

/**
 Creates a function that returns an html code that will be injected into the iframe.
 *
 * @export
 * @param {Partial<ContentInjectionScriptFactoryOptions>} [options] - an additional options that will be used in the production of the html code.
 * @return {ContentInjectionScriptFactory}
 */
export function createContentInjectionScriptFactoryImpl(
  options?: Partial<ContentInjectionScriptFactoryOptions>,
): ContentInjectionScriptFactory {
  function contentInjectionScriptFactory(
    replaceContentMessageType: string,
  ): string {
    return contentInjectionScriptFactoryImpl(replaceContentMessageType, options)
  }
  return contentInjectionScriptFactory
}
