/**
 * IFrameDocumentPostProcessor that identifies link elements
 * and adds the `crossorigin` attribute accordingly
 *
 * Ideally should only be invoked if the resources are encrypted.
 * Currently this processor itself does not check if each resource is encrypted,
 * so there is no conditional processing.
 *
 * @export
 * @param {Document} document - processor parameters
 * @return {Promise<void>}
 */
export function crossoriginProcessor(document: Document): void {
  if (typeof document !== 'object') {
    throw new Error('The document should be an object')
  }

  // Process links
  document.querySelectorAll('link').forEach(processElement)
}

function processElement(element: HTMLElement) {
  const attr = element.getAttribute('href')

  if (attr && !isAbsolute(attr) && !element.getAttribute('crossorigin')) {
    element.setAttribute('crossorigin', 'anonymous')
  }
}

function isAbsolute(uri: string) {
  return uri.indexOf('://') > 0 || uri.indexOf('//') === 0
}
