import { DatasetPropertyImageIsCopiedToCanvas } from './const'

/**
 * Sets a property that marks the target image
 * that has been copied into Canvas.
 *
 * @export
 * @param {HTMLImageElement} htmlImage
 */
export function setDatasetPropertyImageIsCopiedToCanvas(
  htmlImage: HTMLImageElement,
): void {
  if (!htmlImage) {
    throw new Error('The argument should be defined')
  }
  if (typeof htmlImage !== 'object') {
    throw new Error('The argument should be an object')
  }
  htmlImage.dataset[DatasetPropertyImageIsCopiedToCanvas] = 'true'
}
