import type { OriginalImageElement } from '../../types'

import { DatasetPropertyImageIsCopiedToCanvas } from './const'

/**
 * Checks if an image has been processed and copied into
 * a Canvas element.
 *
 * @export
 * @param {OriginalImageElement} htmlImage
 * @return {boolean}
 */
export function checkIfImageIsCopiedToCanvas(
  htmlImage: OriginalImageElement,
): boolean {
  if (!htmlImage) {
    throw new Error('The argument should be defined')
  }
  if (typeof htmlImage !== 'object') {
    throw new Error('The argument should be an object')
  }
  return Boolean(htmlImage.dataset[DatasetPropertyImageIsCopiedToCanvas])
}
