import { WaitImagesDimensions } from '../navigator/iframe-loader'

export class WaitImagesDimensionsImpl implements WaitImagesDimensions {
  public async waitAllImagesHaveDimension(
    images: HTMLImageElement[],
  ): Promise<void> {
    const imagesToLoad: HTMLImageElement[] = images.filter((image) => {
      if (!image.currentSrc) {
        // skip images without url
        return false
      }
      this.forceImageStartLoading(image)
      return image
    })

    await this.waitAllImagesHaveWidthOrLoaded(imagesToLoad)
  }

  protected async waitAllImagesHaveWidthOrLoaded(
    imagesPendingWithoutWidth: HTMLImageElement[],
  ): Promise<void> {
    let imagesWithoutWidth = [...imagesPendingWithoutWidth]
    while (imagesWithoutWidth.length) {
      await new Promise((res) => {
        requestAnimationFrame(res)
      })
      // wait until the image is fully loaded or has the width
      imagesWithoutWidth = this.filterImagesWithWidthOrLoaded(
        imagesWithoutWidth,
      )
    }
  }

  protected forceImageStartLoading(image: HTMLImageElement): void {
    image.loading = 'eager'
    image.decoding = 'async'
    // start loading the image
    image.decode()
  }

  protected filterImagesWithWidthOrLoaded(
    images: HTMLImageElement[],
  ): HTMLImageElement[] {
    return images.filter((image) => !image.width && !image.complete)
  }
}
