import type {
  ContentViewProperties,
  PageLabelInfoWithPosition,
  PageLabelVisibilityHandler,
  Rect,
  VisiblePageLabelsInfoListener,
  VisiblePageLabelsInfoListenerParameters,
  PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
  ElementOffset,
} from '../types'
import { applyToStyleDeclaration } from '../../utils/css-rules'

import { CSSRules, PageLabelOnScreenSide, ViewOffsets } from './types'
import type { VisibleRangeUpdate, PageLabelInfoWithOnScreenSide } from './types'
import { getHTMLElementOffsets } from './utils'
import { PageLabelTransition } from './page-label-transition'

export type PageLabelHash = string

export type PageLabelContentContainerOffsets = ElementOffset

export type PageLabelRendererGetSpineItemViewOffset = (
  spineItemIdx: number,
) => number | undefined

type PageLabelsRendererConstructorParameters = {
  pageLabelsContainer: HTMLElement
  getSpineItemViewOffset: PageLabelRendererGetSpineItemViewOffset
  pageLabelVisibilityHandler: PageLabelVisibilityHandler<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  >
}

export type PageLabelRendererPageLayoutParameters = {
  onePageWidth: number
  numberOfPagesPerSpread: number
  clipContainerWidth: number
  viewOffsets: ViewOffsets
  pageLabelsIFrameContainerOffsets: PageLabelContentContainerOffsets
  bookMargins: number
  columnGap: number
}

const PageLabelViewDefaultStyle: CSSRules = {
  display: 'inline-block',
  fontSize: '12px',
}

const PageLabelTransitionDefaultStyle: CSSRules = {
  transitionTimingFunction: 'ease',
  transitionDuration: '0.1s',
  transitionProperty: 'opacity',
  opacity: '0',
}

export function getStylePropForPageLabelPosition(
  pageLabelPosition: Rect,
  containerOffset: PageLabelContentContainerOffsets,
  iFrameContainerOffset: PageLabelContentContainerOffsets,
  onScreenSide: PageLabelOnScreenSide,
  labelWidth: number,
  labelOffsetFromEdgeOfViewport: number,
  columnGap: number,
): CSSRules {
  const topOffsetAdj = iFrameContainerOffset.top - containerOffset.top
  const topCoordinate = pageLabelPosition.y + topOffsetAdj
  const xOffsetAdjMult = onScreenSide === PageLabelOnScreenSide.Left ? 1 : -1
  const viewMargin = columnGap / 2
  const centerOfPageLabelSpaceAdj = viewMargin / 2
  const halfLabelWidth = labelWidth / 2
  const xOffsetAdj =
    (centerOfPageLabelSpaceAdj -
      halfLabelWidth -
      labelOffsetFromEdgeOfViewport / 2) *
    xOffsetAdjMult
  const resultedLeft = pageLabelPosition.x + xOffsetAdj
  const styleForLabel: CSSRules = {
    top: `${topCoordinate}px`,
    position: 'absolute',
    left: `${resultedLeft}px`,
  }
  return styleForLabel
}

function calcPageLabelHashByInfo(
  pageLabelInfo: PageLabelInfoWithPosition,
): PageLabelHash {
  return `${pageLabelInfo.spineItemIndex}::${pageLabelInfo.type}::${
    pageLabelInfo.location
  }::${pageLabelInfo.label.toLowerCase().trim()}`
}

function removeAllChildrenOfElement(htmlElement: HTMLElement): void {
  const children = htmlElement.children
  while (children.length > 0) {
    children[0].remove()
  }
}

export class PageLabelsRenderer {
  protected get isMultiColumnsMode(): boolean {
    return this.getNumberOfPagesPerSpread() > 1
  }

  private pageLabelsContainer: HTMLElement
  private pageLabelsContainerOffsets: PageLabelContentContainerOffsets
  private pageLabelsIFrameContainerOffsets: PageLabelContentContainerOffsets = {
    top: 0,
    left: 0,
  }

  private pageLabelsElementsOnScreenMap: Map<
    PageLabelHash,
    HTMLElement
  > = new Map()

  private spineItemsRenderSideMap: Map<
    number,
    PageLabelOnScreenSide
  > = new Map()

  private currentPageLabelsInfoWithPosition: PageLabelInfoWithPosition[] = []

  private currentPageLabelsInfoWithPositionMap: Map<
    PageLabelHash,
    PageLabelInfoWithPosition
  > = new Map()

  private pageLabelsTransitionStateMap: Map<
    PageLabelHash,
    PageLabelTransition
  > = new Map()

  private onePageWidth = 0
  private numberOfPagesPerSpread = 1

  private pageLabelWidthsCached: Map<string, number> = new Map()

  private getSpineItemViewOffset: PageLabelRendererGetSpineItemViewOffset

  private bookMargins = 0

  private columnGap: number
  private pageLabelVisibilityHandler: PageLabelVisibilityHandler<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  >
  private visiblePageLabelsInfoOrNull: VisiblePageLabelsInfoListenerParameters<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  > | null = null

  constructor(parameters: PageLabelsRendererConstructorParameters) {
    const {
      pageLabelsContainer,
      getSpineItemViewOffset,
      pageLabelVisibilityHandler,
    } = parameters

    this.getSpineItemViewOffset = getSpineItemViewOffset

    this.pageLabelsContainer = pageLabelsContainer
    this.pageLabelVisibilityHandler = pageLabelVisibilityHandler
    this.setVisiblePageLabelsInfoHandler()
    this.updateRightAndLeftContainerOffsets()
  }

  public renderPageLabels(): void {
    this.renderCurrentScreenPageLabels()
  }

  public recalculateVisibility(): void {
    this.recalculateCurrentPageLabelsVisibility()
  }

  public handleVisibleRangeUpdate(
    visibleRangeUpdate: VisibleRangeUpdate,
  ): void {
    const {
      actualStartOffset,
      actualEndOffset,
      spineItemIndex,
      isFirstVisible,
    } = visibleRangeUpdate

    if (!this.isMultiColumnsMode) {
      return
    }

    let startRenderingOnTheLeftSpread = true
    const visiblePageCount = actualEndOffset - actualStartOffset

    if (visiblePageCount >= 2) {
      startRenderingOnTheLeftSpread = actualStartOffset % 2 === 0
    } else {
      if (actualStartOffset !== 0) {
        console.error('unexpected page index:', actualStartOffset)
      }
      startRenderingOnTheLeftSpread = isFirstVisible
    }

    const spineItemsRenderSideMap = this.spineItemsRenderSideMap
    const currentSideForSpineItem:
      | PageLabelOnScreenSide
      | undefined = spineItemsRenderSideMap.get(spineItemIndex)
    const updatedSideForSpineItem: PageLabelOnScreenSide = startRenderingOnTheLeftSpread
      ? PageLabelOnScreenSide.Left
      : PageLabelOnScreenSide.Right

    if (currentSideForSpineItem !== updatedSideForSpineItem) {
      spineItemsRenderSideMap.set(spineItemIndex, updatedSideForSpineItem)
      this.updateRightAndLeftContainerOffsets()
    }
  }

  public updatePageLabelsInfo(
    pageLabelsInfo: PageLabelInfoWithPosition[],
  ): void {
    this.mergeWithPageLabelsInfo(pageLabelsInfo)
  }

  public updateLayoutParameters(
    pageLayoutParameters: PageLabelRendererPageLayoutParameters,
  ): void {
    this.setPageLayoutParameters(pageLayoutParameters)
  }

  public removeVisiblePageLabels(): void {
    this.removeCurrentPageLabelsFromDOM()
    this.resetTransitionStateForPageLabels()
  }

  protected setPageLayoutParameters(
    pageLayoutParameters: PageLabelRendererPageLayoutParameters,
  ): void {
    const {
      numberOfPagesPerSpread,
      onePageWidth,
      clipContainerWidth,
      viewOffsets,
      pageLabelsIFrameContainerOffsets,
      bookMargins,
      columnGap,
    } = pageLayoutParameters

    this.numberOfPagesPerSpread = numberOfPagesPerSpread
    this.onePageWidth = onePageWidth
    this.pageLabelsIFrameContainerOffsets = pageLabelsIFrameContainerOffsets
    this.bookMargins = bookMargins
    this.columnGap = columnGap

    const {
      startOffset: viewStartOffset,
      endOffset: viewEndOffset,
    } = viewOffsets
    const contentViewAttributes: ContentViewProperties<PageLabelVisibilityHandlerReflowableLayoutBookTypeName> = {
      viewEndOffset,
      viewStartOffset,
      contentVisibleAdditionalWidth: clipContainerWidth,
    }

    this.pageLabelVisibilityHandler.setContentViewProperties(
      contentViewAttributes,
    )
    this.updateRightAndLeftContainerOffsets()
  }

  private calcPageLabelHashByInfo = (
    pageLabelInfoWithPosition: PageLabelInfoWithPosition,
  ): PageLabelHash => {
    return calcPageLabelHashByInfo(pageLabelInfoWithPosition)
  }

  protected areEqualLabelViews(
    pageLabelInfoA: PageLabelInfoWithPosition,
    pageLabelInfoB: PageLabelInfoWithPosition,
  ): boolean {
    return (
      this.calcPageLabelHashByInfo(pageLabelInfoA) ===
      this.calcPageLabelHashByInfo(pageLabelInfoB)
    )
  }

  protected mergeWithPageLabelsInfo(
    pageLabelsInfo: PageLabelInfoWithPosition[],
  ): void {
    const pageLabelInfoMap = this.currentPageLabelsInfoWithPositionMap

    pageLabelsInfo.forEach((pageLabelInfo) => {
      const pageLabelHash: PageLabelHash = this.calcPageLabelHashByInfo(
        pageLabelInfo,
      )
      const pageLabelInfoCurrentOrUndefined:
        | PageLabelInfoWithPosition
        | undefined = pageLabelInfoMap.get(pageLabelHash)
      const pageLabelInfoCurrentTimestampMs: number =
        pageLabelInfoCurrentOrUndefined?.timestampMs ?? Number.NEGATIVE_INFINITY
      const pageLabelInfoUpdatedTimestampMs: number = pageLabelInfo.timestampMs

      // TODO - we need to create a class for page label info
      if (pageLabelInfoUpdatedTimestampMs > pageLabelInfoCurrentTimestampMs) {
        pageLabelInfoMap.set(pageLabelHash, pageLabelInfo)
      }
    })
    this.setCurrentPageLabelsInfoWithPosition(
      Array.from(pageLabelInfoMap.values()),
    )
  }

  protected updateRightAndLeftContainerOffsets(): void {
    this.pageLabelsContainerOffsets = getHTMLElementOffsets(
      this.pageLabelsContainer,
    )
  }

  protected recalculateCurrentPageLabelsVisibility(): void {
    this.recalculatePageLabelsVisibility(this.currentPageLabelsInfoWithPosition)
  }

  protected renderCurrentScreenPageLabels(): void {
    const visiblePageLabelsInfoOrNull = this.visiblePageLabelsInfoOrNull
    if (!visiblePageLabelsInfoOrNull) {
      return
    }
    const {
      visibleOnWiderScreenPageLabelsInfo,
      contentViewProperties,
    } = visiblePageLabelsInfoOrNull
    const { viewStartOffset, viewEndOffset } = contentViewProperties
    const viewOffsets: ViewOffsets = {
      endOffset: viewEndOffset,
      startOffset: viewStartOffset,
    }
    // those page labels that are visible on a screen that is wider than the actual
    // screen size should be handled for animation maintenance
    this.handlePageLabelsVisibleOnScreenWithAdditionalWidth(
      visibleOnWiderScreenPageLabelsInfo,
      viewOffsets,
    )
  }

  protected setCurrentPageLabelsInfoWithPosition(
    pageLabelsInfo: PageLabelInfoWithPosition[],
  ): void {
    this.currentPageLabelsInfoWithPosition = pageLabelsInfo
  }

  private removePageLabelViewRenderedByHash = (
    pageLabelInfoHash: PageLabelHash,
  ): void => {
    const pageLabelsElementsOnScreen = this.pageLabelsElementsOnScreenMap
    pageLabelsElementsOnScreen.get(pageLabelInfoHash)?.remove()
    pageLabelsElementsOnScreen.delete(pageLabelInfoHash)
  }

  protected removePageLabelsViewsElementsByHashes(
    pageLabelsViewsToRemoveHashes: PageLabelHash[],
  ): void {
    pageLabelsViewsToRemoveHashes.forEach(
      this.removePageLabelViewRenderedByHash,
    )
  }

  protected getOnScreenPageLabelsViewsHashes(): PageLabelHash[] {
    return Array.from(this.pageLabelsElementsOnScreenMap.keys())
  }

  protected removeCurrentPageLabelsFromDOM(): void {
    removeAllChildrenOfElement(this.pageLabelsContainer)
    this.pageLabelsElementsOnScreenMap.clear()
  }

  protected getViewportSpineItemViewOffset(spineItemIndex: number): number {
    const offsetForSpineItem = this.getSpineItemViewOffset(spineItemIndex)

    if (typeof offsetForSpineItem === 'number') {
      return offsetForSpineItem
    }
    return Number.POSITIVE_INFINITY
  }

  protected getPageLabelTotalXOffset(
    spineItemIndex: number,
    pageLabelPosition: Rect,
  ): number {
    const spineItemXOffset = this.getViewportSpineItemViewOffset(spineItemIndex)
    return pageLabelPosition.x + Number(spineItemXOffset)
  }

  protected getPageWidth(): number {
    return this.onePageWidth
  }

  protected getPagesWidth(pagesCount: number): number {
    return pagesCount * this.getPageWidth()
  }

  protected getPageLabelWidthFromCache(
    pageLabelsInfo: PageLabelInfoWithPosition,
  ): number | null {
    const pageLabelHash = this.calcPageLabelHashByInfo(pageLabelsInfo)

    return this.pageLabelWidthsCached.get(pageLabelHash) ?? null
  }

  protected savePageLabelWidthToCache(
    pageLabelsInfo: PageLabelInfoWithPosition,
    pageLabelWidth: number,
  ): void {
    const pageLabelHash = this.calcPageLabelHashByInfo(pageLabelsInfo)

    this.pageLabelWidthsCached.set(pageLabelHash, pageLabelWidth)
  }

  protected calculatePageLabelWidth(label: string): number {
    const pageLabelElement = this.createPageLabelViewElementAndApplyDefaultStyle(
      label,
    )

    pageLabelElement.style.visibility = 'hidden'
    this.pageLabelsContainer.appendChild(pageLabelElement)
    const pageLabelElementWidth = pageLabelElement.getBoundingClientRect().width

    pageLabelElement.remove()
    return pageLabelElementWidth
  }

  protected getPageLabelWidth(
    pageLabelInfo: PageLabelInfoWithPosition,
  ): number {
    const cachedWidth = this.getPageLabelWidthFromCache(pageLabelInfo)

    if (cachedWidth) {
      return cachedWidth
    }

    const pageLabelElementWidth: number = this.calculatePageLabelWidth(
      pageLabelInfo.label,
    )
    this.savePageLabelWidthToCache(pageLabelInfo, pageLabelElementWidth)
    return pageLabelElementWidth
  }

  protected getPageIdxForOffset(xOffset: number): number {
    const onePageWidth = this.getPageWidth()
    return Math.max(Math.floor(xOffset / onePageWidth), 0)
  }

  protected getNumberOfPagesPerSpread(): number {
    return this.numberOfPagesPerSpread
  }

  protected mergePageLabelInfoAndPageOffset(
    pageLabelInfoWithPosition: PageLabelInfoWithPosition,
    positionXOffset: number,
    onScreenSide: PageLabelOnScreenSide,
    pageLabelWidth: number,
  ): PageLabelInfoWithOnScreenSide {
    return {
      ...pageLabelInfoWithPosition,
      position: {
        ...pageLabelInfoWithPosition.position,
        x: positionXOffset,
      },
      onScreenSide,
      pageLabelWidth,
    }
  }

  protected getPageSideForFirstPageOfSpine(
    spineItemIdx: number,
  ): PageLabelOnScreenSide {
    return (
      this.spineItemsRenderSideMap.get(spineItemIdx) ??
      PageLabelOnScreenSide.Left
    )
  }

  protected getPageLabelSideOnSpread(
    pageLabelSpineItemIdx: number,
    pageLabelPagesCountFromBeginnigOfSpineItem: number,
  ): PageLabelOnScreenSide {
    if (!this.isMultiColumnsMode) {
      return PageLabelOnScreenSide.Left
    }

    const onScreenSideForSpineFirstPage = this.getPageSideForFirstPageOfSpine(
      pageLabelSpineItemIdx,
    )
    const isLeftScreenSideForSpineFirstPage =
      onScreenSideForSpineFirstPage === PageLabelOnScreenSide.Left
    const spinePageIdxFromSpreadStart = isLeftScreenSideForSpineFirstPage
      ? 0
      : 1
    const isEvenPageFromSpreadStart =
      (pageLabelPagesCountFromBeginnigOfSpineItem +
        spinePageIdxFromSpreadStart) %
        2 ===
      0

    return isEvenPageFromSpreadStart
      ? PageLabelOnScreenSide.Left
      : PageLabelOnScreenSide.Right
  }

  protected getPageLabelsWithSpineItemsOffsets(
    pageLabelsInfo: PageLabelInfoWithPosition[],
  ): PageLabelInfoWithOnScreenSide[] {
    return pageLabelsInfo.map((pageLabelInfoWithPosition) => {
      const { spineItemIndex, position } = pageLabelInfoWithPosition
      const actualSpineItemOffset = this.getViewportSpineItemViewOffset(
        spineItemIndex,
      )

      if (!Number.isFinite(actualSpineItemOffset)) {
        return this.mergePageLabelInfoAndPageOffset(
          pageLabelInfoWithPosition,
          Number.POSITIVE_INFINITY,
          PageLabelOnScreenSide.Left,
          0,
        )
      }

      const pageLabelPagesCountFromBeginnigOfSpineItem = this.getPageIdxForOffset(
        position.x,
      )
      const pageLabelSideOnSpread = this.getPageLabelSideOnSpread(
        spineItemIndex,
        pageLabelPagesCountFromBeginnigOfSpineItem,
      )
      const pageLabelOffsetFromStartOfSpine = this.getPagesWidth(
        pageLabelPagesCountFromBeginnigOfSpineItem,
      )
      const currentViewLeftEdgeOffsetFromStartOfSpine =
        actualSpineItemOffset + pageLabelOffsetFromStartOfSpine
      const pageLabelWidth = this.getPageLabelWidth(pageLabelInfoWithPosition)
      const pageLabelOffsetFromLeftEdgeOfCurrentView =
        pageLabelSideOnSpread === PageLabelOnScreenSide.Left
          ? 0
          : this.getPagesWidth(1) - pageLabelWidth - 1
      const pageLabelAdjustedToSpareEndTotalXOffset =
        currentViewLeftEdgeOffsetFromStartOfSpine +
        pageLabelOffsetFromLeftEdgeOfCurrentView

      return this.mergePageLabelInfoAndPageOffset(
        pageLabelInfoWithPosition,
        pageLabelAdjustedToSpareEndTotalXOffset,
        pageLabelSideOnSpread,
        pageLabelWidth,
      )
    })
  }

  protected recalculatePageLabelsVisibility(
    pageLabelsInfoRaw: PageLabelInfoWithPosition[],
  ): void {
    const pageLabelsInfo: PageLabelInfoWithOnScreenSide[] = this.getPageLabelsWithSpineItemsOffsets(
      pageLabelsInfoRaw,
    )
    this.updatePageLabelsVisibilityState(pageLabelsInfo)
  }

  protected handlePageLabelsVisibleOnScreenWithAdditionalWidth(
    pageLabelsViewsVisible: PageLabelInfoWithOnScreenSide[],
    viewOffsets: ViewOffsets,
  ): void {
    const pageLabelsViewsVisibleHashes: PageLabelHash[] = pageLabelsViewsVisible.map(
      this.calcPageLabelHashByInfo,
    )
    const pageLabelsViewsToRenderOrRerender: PageLabelInfoWithOnScreenSide[] = this.getPageLabelsViewsNotRenderedOnTheScreenOrWithPositionChanged(
      pageLabelsViewsVisible,
      pageLabelsViewsVisibleHashes,
    )
    const pageLabelsViewsHashesToRemove: PageLabelHash[] = this.getPageLabelsViewsToRemove(
      pageLabelsViewsVisibleHashes,
    )

    this.removePageLabelsViewsElementsByHashes(pageLabelsViewsHashesToRemove)
    this.renderOrUpdatePageLabelsViews(pageLabelsViewsToRenderOrRerender)
    this.applyTransitionAnimation(
      pageLabelsViewsVisible,
      pageLabelsViewsVisibleHashes,
      viewOffsets,
    )
  }

  protected getTransitionStateOrNullForPageLabelByHash(
    pageLabelHash: PageLabelHash,
  ): PageLabelTransition | null {
    return this.pageLabelsTransitionStateMap.get(pageLabelHash) ?? null
  }

  protected setTransitionStateForPageLabelByHash(
    pageLabelHash: PageLabelHash,
    pageLabelTransition: PageLabelTransition,
  ): void {
    this.pageLabelsTransitionStateMap.set(pageLabelHash, pageLabelTransition)
  }

  protected resetTransitionStateForPageLabels(): void {
    this.pageLabelsTransitionStateMap.clear()
  }

  protected getTransitionStateForPageLabelsByHash(
    pageLabelHash: PageLabelHash,
  ): PageLabelTransition {
    return (
      this.getTransitionStateOrNullForPageLabelByHash(pageLabelHash) ??
      new PageLabelTransition()
    )
  }

  protected applyTransitionAnimation(
    pageLabelsViewsVisibleOnExtendedScreen: PageLabelInfoWithOnScreenSide[],
    pageLabelsViewsVisibleOnExtendedScreenHashes: PageLabelHash[],
    viewOffsets: ViewOffsets,
  ): void {
    pageLabelsViewsVisibleOnExtendedScreen.forEach(
      (pageLabelViewVisible, idx) => {
        const pageLabelViewHash =
          pageLabelsViewsVisibleOnExtendedScreenHashes[idx]

        if (!pageLabelViewHash) {
          throw new Error(
            `Hash's not found for a page label with index ${pageLabelViewHash}`,
          )
        }

        const pageLabelViewHTMLElement: HTMLElement | null = this.getElementOrNullForPageLabelHash(
          pageLabelViewHash,
        )

        if (!pageLabelViewHTMLElement) {
          return
        }

        const { position, onScreenSide } = pageLabelViewVisible
        const transition = this.getTransitionStateForPageLabelsByHash(
          pageLabelViewHash,
        )
        transition.updatePositions({
          pageLabelTotalXOffset: position.x,
          pageLabelOnScreenSide: onScreenSide,
          viewOffsets,
        })
        this.applyHtmlElementStyle(
          pageLabelViewHTMLElement,
          transition.getStyle(),
        )
        this.setTransitionStateForPageLabelByHash(pageLabelViewHash, transition)
      },
    )
  }

  protected getElementOrNullForPageLabelHash(
    pageLabelHash: PageLabelHash,
  ): HTMLElement | null {
    return this.pageLabelsElementsOnScreenMap.get(pageLabelHash) ?? null
  }

  protected getElementForPageLabelViewOrNull(
    pageLabelView: PageLabelInfoWithPosition,
  ): HTMLElement | null {
    const pageLabelHash = this.calcPageLabelHashByInfo(pageLabelView)
    return this.getElementOrNullForPageLabelHash(pageLabelHash) ?? null
  }

  protected areEqualPageLabelsXYCoordinates(
    pageLabelPositionA: Rect,
    pageLabelPositionB: Rect,
  ): boolean {
    return (
      pageLabelPositionA.x === pageLabelPositionB.x &&
      pageLabelPositionA.y === pageLabelPositionA.y
    )
  }

  protected getPageLabelsViewsNotRenderedOnTheScreenOrWithPositionChanged(
    pageLabelsViewsVisible: PageLabelInfoWithOnScreenSide[],
    pageLabelsViewsVisibleHashes: PageLabelHash[],
  ): PageLabelInfoWithOnScreenSide[] {
    return pageLabelsViewsVisible.filter(
      (pageLabelViewVisible, idx): boolean => {
        const pageLabelViewVisibleHash = pageLabelsViewsVisibleHashes[idx]
        if (!pageLabelViewVisibleHash) {
          throw new Error('Hash for page label is not defined')
        }
        if (!this.pageLabelsElementsOnScreenMap.get(pageLabelViewVisibleHash)) {
          // page label is not on the screen
          return true
        }

        const samePageLabelOnScreen:
          | PageLabelInfoWithPosition
          | undefined = this.currentPageLabelsInfoWithPositionMap.get(
          pageLabelViewVisibleHash,
        )

        if (samePageLabelOnScreen) {
          return !this.areEqualPageLabelsXYCoordinates(
            samePageLabelOnScreen.position,
            pageLabelViewVisible.position,
          )
        }
        return true
      },
    )
  }

  protected getPageLabelsViewsToRemove(
    pageLabelsViewsVisibleHashes: PageLabelHash[],
  ): PageLabelHash[] {
    const onScreenPageLabelsHashes: PageLabelHash[] = this.getOnScreenPageLabelsViewsHashes()
    return onScreenPageLabelsHashes.filter(
      (pageLabelViewOnScreenHash: PageLabelHash): boolean => {
        return !pageLabelsViewsVisibleHashes.includes(pageLabelViewOnScreenHash)
      },
    )
  }

  protected updatePageLabelsVisibilityState(
    pageLabelsInfo: PageLabelInfoWithOnScreenSide[],
  ): void {
    this.pageLabelVisibilityHandler.updatePageLabelsVisibility(pageLabelsInfo)
  }

  protected addPageLabelElementToTheListOfOnScreenElements(
    pageLabelElement: HTMLElement,
    pageLabelView: PageLabelInfoWithPosition,
  ) {
    const pageLabelViewHash = this.calcPageLabelHashByInfo(pageLabelView)
    this.pageLabelsElementsOnScreenMap.set(pageLabelViewHash, pageLabelElement)
  }

  protected applyDefaultStyleToElement(element: HTMLElement): void {
    this.applyHtmlElementStyle(element, PageLabelViewDefaultStyle)
    this.applyHtmlElementStyle(element, PageLabelTransitionDefaultStyle)
  }

  protected getBookEdgeToPageLabelOffset(): number {
    return this.bookMargins
  }

  protected getStyleForPageLabelPosition(
    pageLabelViewPosition: Rect,
    onScreenSide: PageLabelOnScreenSide,
    pageLabelWidth: number,
  ): CSSRules {
    const containerForTheLabelOffsets: PageLabelContentContainerOffsets = this
      .pageLabelsContainerOffsets
    return getStylePropForPageLabelPosition(
      pageLabelViewPosition,
      containerForTheLabelOffsets,
      this.pageLabelsIFrameContainerOffsets,
      onScreenSide,
      pageLabelWidth,
      this.getBookEdgeToPageLabelOffset(),
      this.columnGap,
    )
  }

  protected applyHtmlElementStyle(element: HTMLElement, style: CSSRules) {
    applyToStyleDeclaration(element.style, style)
  }

  protected createPageLabelViewElement(label: string): HTMLElement {
    const pageLabelElement = document.createElement('div')

    pageLabelElement.innerHTML = label
    pageLabelElement.className = 'flowpub-page-label-element'
    return pageLabelElement
  }

  protected createPageLabelViewElementAndApplyDefaultStyle(
    label: string,
  ): HTMLElement {
    const pageLabelElement = this.createPageLabelViewElement(label)

    this.applyDefaultStyleToElement(pageLabelElement)
    return pageLabelElement
  }

  protected attachPageLabelViewElementToContainer(
    pageLabelElement: HTMLElement,
  ): void {
    const containerForTheLabel: HTMLElement = this.pageLabelsContainer
    containerForTheLabel.appendChild(pageLabelElement)
  }

  protected createAndRenderElementForPageLabelView(
    pageLabelView: PageLabelInfoWithPosition,
  ): HTMLElement {
    const pageLabelElement: HTMLElement = this.createPageLabelViewElementAndApplyDefaultStyle(
      pageLabelView.label,
    )
    this.addPageLabelElementToTheListOfOnScreenElements(
      pageLabelElement,
      pageLabelView,
    )
    this.attachPageLabelViewElementToContainer(pageLabelElement)
    return pageLabelElement
  }

  protected renderOrUpdatePageLabelsViews(
    pageLabelViews: PageLabelInfoWithOnScreenSide[],
  ): void {
    for (const pageLabelView of pageLabelViews) {
      const currentElement: HTMLElement =
        this.getElementForPageLabelViewOrNull(pageLabelView) ??
        this.createAndRenderElementForPageLabelView(pageLabelView)
      const { onScreenSide, position, pageLabelWidth } = pageLabelView
      const updatedStylesForPageLabelElement = this.getStyleForPageLabelPosition(
        position,
        onScreenSide,
        pageLabelWidth,
      )

      this.applyHtmlElementStyle(
        currentElement,
        updatedStylesForPageLabelElement,
      )
    }
  }

  protected setVisiblePageLabelsInfoHandler() {
    this.pageLabelVisibilityHandler.addVisiblePageLabelsInfoListener(
      this.visiblePageLabelsInfoListener,
    )
  }

  private visiblePageLabelsInfoListener: VisiblePageLabelsInfoListener<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  > = (
    pageLabelsVisibilityInfo: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName
    >,
  ): void => {
    this.visiblePageLabelsInfoOrNull = pageLabelsVisibilityInfo
  }
}
