import { PageLabelOnScreenSide, ViewOffsets, CSSRules } from './types'

type PageLabelTransitionPositionsUpdateParameters = {
  pageLabelTotalXOffset: number
  pageLabelOnScreenSide: PageLabelOnScreenSide
  viewOffsets: ViewOffsets
}

enum Direction {
  Towards = 'TOWARDS',
  Backwards = 'BACKWARDS',
}

enum BreakPoints {
  StartTransition = 'START_TRANSITION',
  EndTransition = 'END_TRANSITION',
}

export type PercentOfPageVisibility = number

export type OpacityTransitionParametersForDirection = {
  [BreakPoints.EndTransition]: PercentOfPageVisibility
  [BreakPoints.StartTransition]: PercentOfPageVisibility
}

type OpacityTransitionParameters = {
  [Direction.Backwards]: OpacityTransitionParametersForDirection
  [Direction.Towards]: OpacityTransitionParametersForDirection
}

type OpacityTransitionCalcParameters = {
  distanceFromEdgeOfScreen: number
  viewWidth: number
  directionOfTransition: Direction
}

const OpacityTransitionDescription: OpacityTransitionParameters = {
  [Direction.Backwards]: {
    [BreakPoints.EndTransition]: 50,
    [BreakPoints.StartTransition]: 0,
  },
  [Direction.Towards]: {
    [BreakPoints.EndTransition]: 100,
    [BreakPoints.StartTransition]: 50,
  },
}

export class OpacityTransition {
  constructor(private transitionParameters: OpacityTransitionParameters) {}
  public calcOpacity(parameters: OpacityTransitionCalcParameters): string {
    const {
      distanceFromEdgeOfScreen,
      viewWidth,
      directionOfTransition,
    } = parameters

    if (Math.abs(distanceFromEdgeOfScreen) > viewWidth) {
      return '0'
    }

    switch (directionOfTransition) {
      case Direction.Towards: {
        return this.getOpacityForTowardsDirection(
          distanceFromEdgeOfScreen,
          viewWidth,
        )
      }
      case Direction.Backwards: {
        return this.getOpacityForBackwardsDirection(
          distanceFromEdgeOfScreen,
          viewWidth,
        )
      }
      default:
        return '0'
    }
  }

  protected getOpacityForTowardsDirection(
    distanceFromEdgeOfScreen: number,
    viewWidth: number,
  ): string {
    const {
      [BreakPoints.StartTransition]: transitionDescriptionStartPercent,
      [BreakPoints.EndTransition]: transitionDescriptionEndPercent,
    } = this.transitionParameters[Direction.Towards]
    const visiblePartWidth = viewWidth - Math.abs(distanceFromEdgeOfScreen)
    const visiblePartWidthPercent = (visiblePartWidth / viewWidth) * 100

    if (visiblePartWidthPercent > transitionDescriptionEndPercent) {
      return '1'
    }
    if (visiblePartWidthPercent < transitionDescriptionStartPercent) {
      return '0'
    }
    const visibility =
      (visiblePartWidthPercent - transitionDescriptionStartPercent) /
      (transitionDescriptionEndPercent - transitionDescriptionStartPercent)

    return String(visibility)
  }

  protected getOpacityForBackwardsDirection(
    distanceFromEdgeOfScreen: number,
    viewWidth: number,
  ): string {
    const {
      [BreakPoints.StartTransition]: transitionDescriptionStartPercent,
      [BreakPoints.EndTransition]: transitionDescriptionEndPercent,
    } = this.transitionParameters[Direction.Backwards]
    const hiddenPartWidth = Math.abs(distanceFromEdgeOfScreen)
    const hiddenPartWidthPercent = (hiddenPartWidth / viewWidth) * 100

    if (hiddenPartWidthPercent > transitionDescriptionEndPercent) {
      return '0'
    }
    if (hiddenPartWidthPercent < transitionDescriptionStartPercent) {
      return '1'
    }
    const invisibility =
      (hiddenPartWidthPercent - transitionDescriptionStartPercent) /
      (transitionDescriptionEndPercent - transitionDescriptionStartPercent)
    const visibility = 1 - invisibility

    return String(visibility)
  }
}

export class PageLabelTransition {
  private pageLabelTotalXOffset: number
  private pageLabelOnScreenSide: PageLabelOnScreenSide
  private viewOffsets: ViewOffsets
  private distanceFromEdgeOfScreen: number = Number.POSITIVE_INFINITY
  private style: CSSRules = {}
  private directionOfTransition: Direction = Direction.Towards
  private opacityTransition = new OpacityTransition(
    OpacityTransitionDescription,
  )
  protected get viewWidth(): number {
    const { endOffset, startOffset } = this.viewOffsets
    return endOffset - startOffset
  }

  public getStyle(): CSSRules {
    return this.style
  }

  public updatePositions(
    parameters: PageLabelTransitionPositionsUpdateParameters,
  ): void {
    const {
      pageLabelTotalXOffset,
      pageLabelOnScreenSide,
      viewOffsets,
    } = parameters

    this.pageLabelTotalXOffset = pageLabelTotalXOffset
    this.pageLabelOnScreenSide = pageLabelOnScreenSide
    this.handleUpdatedViewOffset(viewOffsets)
  }

  public handleUpdatedViewOffset(offsets: ViewOffsets): void {
    this.viewOffsets = offsets
    this.updateState()
  }

  protected updateState(): void {
    const { viewOffsets } = this

    this.updateDirectionOfTransition(viewOffsets)
    this.updateDistanceFromEdgeOfScreen(viewOffsets)
    this.updateStyle()
  }

  protected updateStyle(): void {
    this.style = this.calculateAndReturnStyle()
  }

  protected getDistanceFromLabel(viewOffsets: ViewOffsets): number {
    const { pageLabelTotalXOffset, pageLabelOnScreenSide: onScreenSide } = this
    const {
      startOffset: viewStartOffset,
      endOffset: viewEndOffset,
    } = viewOffsets
    const screenXOffsetForPageLabelSide: number =
      onScreenSide === PageLabelOnScreenSide.Left
        ? viewStartOffset
        : viewEndOffset
    return screenXOffsetForPageLabelSide - pageLabelTotalXOffset
  }

  protected updateDistanceFromEdgeOfScreen(viewOffsets: ViewOffsets): void {
    this.distanceFromEdgeOfScreen = this.getDistanceFromLabel(viewOffsets)
  }

  protected calculateAndReturnOpacity(): string {
    const {
      distanceFromEdgeOfScreen,
      viewWidth,
      directionOfTransition,
      opacityTransition,
    } = this
    const opacityValue = opacityTransition.calcOpacity({
      distanceFromEdgeOfScreen,
      viewWidth,
      directionOfTransition,
    })

    return opacityValue
  }

  protected calculateAndReturnStyle(): CSSRules {
    return {
      opacity: this.calculateAndReturnOpacity(),
    }
  }

  protected getDirectionOfTransition(
    updatedViewOffsets: ViewOffsets,
  ): Direction {
    const updatedDistance = Math.abs(
      this.getDistanceFromLabel(updatedViewOffsets),
    )
    const { distanceFromEdgeOfScreen } = this
    if (updatedDistance - Math.abs(distanceFromEdgeOfScreen) > 0) {
      return Direction.Backwards
    }
    return Direction.Towards
  }

  protected updateDirectionOfTransition(updatedViewOffsets: ViewOffsets): void {
    this.directionOfTransition = this.getDirectionOfTransition(
      updatedViewOffsets,
    )
  }
}
