import type {
  InstantiateResourceByURL,
  ResourceTypeCSS,
  Resource,
  InjectCSSParameters,
} from '../../navigator'
import { instantiateCSSResourceByUrl } from '../instantiate-css-resource-by-url'

import type { InjectCSSFilesByUrls } from './types'

/**
 * Add html elements with references to remote CSS files
 * into a spine iframe.
 *
 * @param {InjectCSSParameters} parameters
 */
export const injectCSSByFileURLs: InjectCSSFilesByUrls =
  async function injectCSSByFileURLsImpl(
    parameters: InjectCSSParameters,
    instantiateCSSResourceByURL: InstantiateResourceByURL<ResourceTypeCSS> = instantiateCSSResourceByUrl,
  ): Promise<void> {
    const {
      document,
      readiumCssAssetUrlsOrUndefined,
      overrideCssUrlOrUndefined,
      applyResourcesToIframeDocument,
    } = parameters

    const cssResources: Resource<ResourceTypeCSS>[] = []

    /**
     * The order in which CSS should be applied in <head> is:
     * 1) <base> tag
     * 2) beforeCssResource
     * 3) defaultCssResource
     * 4) overrideCssResource
     * 4) all elements that had been already exist in the <head> before the CSS injection
     * 6) afterCssResource
     */

    if (overrideCssUrlOrUndefined) {
      const overrideCssResource = instantiateCSSResourceByURL(
        overrideCssUrlOrUndefined,
      )
      cssResources.push({
        ...overrideCssResource,
        insertion: 'prepend',
      })
    }

    if (readiumCssAssetUrlsOrUndefined) {
      const { beforeCssUrl, defaultCssUrl, afterCssUrl } =
        readiumCssAssetUrlsOrUndefined
      const beforeCssResource = instantiateCSSResourceByURL(beforeCssUrl)
      const defaultCssResource = instantiateCSSResourceByURL(defaultCssUrl)
      const afterCssResource = instantiateCSSResourceByURL(afterCssUrl)
      cssResources.push({
        ...defaultCssResource,
        insertion: 'prepend',
      })
      cssResources.push({
        ...beforeCssResource,
        insertion: 'prepend',
      })
      cssResources.push({
        ...afterCssResource,
        insertion: 'append',
      })
    }

    // Execute injection
    await applyResourcesToIframeDocument(cssResources, document)

    // Move <base> elements to beginning of <head>
    const headElement = document.head
    Array.from(headElement.querySelectorAll('base'))
      .reverse()
      .forEach((baseElement) =>
        headElement.insertBefore(baseElement, headElement.firstChild),
      )
  }
