import {
  checkIfHtmlElement,
  imageToCanvas,
  loadBlobToImage,
  SingletonResizeObserver,
  updatePositionAndSizeToCanvas,
} from '../utils'

import { setDatasetPropertyImageIsCopiedToCanvas } from './set-image-is-copied-to-canvas'
import { CreateImageURLForContent, LoadImageData } from './types'
import { ImageClassNameCanvasWithImgContent } from './const'

export interface ReplaceImageWithCanvasWithoutImageContentExposingFactoryParameters {
  /**
   * Extracts the information that is enough to display image and get its size.
   * The original image itself won't be exposed on the Network tab, because the data
   * is either broken or substituted.
   *
   * @type {ExtractPartialImageContent}
   * @memberof ReplaceImageWithCanvasWithoutImageContentExposingFactoryParameters
   */
  createFakeImageWithSameSizeURL: CreateImageURLForContent
}

/**
 * Copy the image to canvas element and replace the original image with it.
 * The original image will be exposed neither in DOM nor on the Network tab.
 *
 * @export
 * @param {ReplaceImageWithCanvasWithoutImageContentExposingFactoryParameters} parameters
 * @return {LoadImageData}
 */
export function createReplaceImageWithCanvasWithoutImageContentExposing(
  parameters: ReplaceImageWithCanvasWithoutImageContentExposingFactoryParameters,
): LoadImageData {
  const { createFakeImageWithSameSizeURL } = parameters

  if (!createFakeImageWithSameSizeURL) {
    throw new Error(
      '"createFakeImageWithSameSizeURL" is not defined in the parameters',
    )
  }

  // TODO CYP-1164 add test to ensure image sizes are the same after replacement
  async function replaceImageWithCanvasWithoutImageContentExposing(
    imgElement: HTMLImageElement,
    imageBinaryData: ArrayBuffer,
  ): Promise<void> {
    if (!checkIfHtmlElement(imgElement)) {
      throw new Error('The image should be an HTMLElement')
    }
    if (!imageBinaryData) {
      throw new Error('The image data should be defined')
    }
    const fakeImageUrl: string = await createFakeImageWithSameSizeURL(
      imageBinaryData,
    )
    await loadBlobToImage(imgElement, fakeImageUrl)
    // natural width/height are necessary to load the image at full resolution
    const imageWidth = imgElement.naturalWidth
    const imageHeight = imgElement.naturalHeight

    const canvasElement = document.createElement('canvas')
    // Add unique class name for degausser, and degausser will ignore the canvas element
    canvasElement.className = ImageClassNameCanvasWithImgContent
    canvasElement.width = imageWidth
    canvasElement.height = imageHeight

    // TODO: CYP-1306
    const { objectFit, objectPosition } = window.getComputedStyle(imgElement)
    canvasElement.style.objectFit = objectFit
    canvasElement.style.objectPosition = objectPosition

    // update canvas position and size
    updatePositionAndSizeToCanvas(imgElement, canvasElement)

    await imageToCanvas(canvasElement, imageBinaryData, {
      width: imageWidth,
      height: imageHeight,
    })

    if (imgElement.parentNode) {
      imgElement.parentNode.insertBefore(canvasElement, imgElement.nextSibling)
    } else {
      canvasElement.after(imgElement)
    }

    const spineItemWindowOrNull: Window | null =
      imgElement.ownerDocument.defaultView
    if (spineItemWindowOrNull) {
      const imageResizeObserver = SingletonResizeObserver.getInstance(
        spineItemWindowOrNull,
      )
      imageResizeObserver.observe(imgElement)
    }

    setDatasetPropertyImageIsCopiedToCanvas(imgElement)
  }
  return replaceImageWithCanvasWithoutImageContentExposing
}
