import * as parsel from 'parsel-js'

/**
 * Processes a CSS selector that uses namespaces in attribute names
 * @param {string} selector - selector text
 * @returns new selector if a change was needed; undefined otherwise
 */
export function cssSelectorNamespaceProcessor(
  selector: string,
): string | undefined {
  const tree = parsel.parse(selector, { recursive: true })

  // Bail if parsing failed
  if (!tree) {
    return undefined
  }

  let changed = false
  function processNode(node: parsel.AST) {
    if (node.type === 'pseudo-class') {
      const pClass = node as parsel.PseudoClassToken
      if (pClass.subtree) {
        parsel.walk(pClass.subtree, processNode)
        pClass.content = `:${pClass.name}(${customStringify(pClass.subtree)})`
      }
    } else if (node.type === 'attribute') {
      const attribute = node as parsel.AttributeToken
      if (attribute.namespace) {
        attribute.content =
          `[${attribute.namespace}\\:${attribute.name}` +
          `${attribute.operator ?? ''}${attribute.value ?? ''}` +
          `${attribute.caseSensitive ?? ''}]`
        changed = true
      }
    }
  }

  parsel.walk(tree, processNode)
  return changed ? customStringify(tree) : undefined
}

function customStringify(node: parsel.AST): string {
  switch (node.type) {
    case 'complex': {
      const joinStr =
        node.combinator.trim() === '' ? ' ' : ` ${node.combinator} `
      return (
        `${customStringify(node.left)}` +
        `${joinStr}${customStringify(node.right)}`
      )
    }
    case 'compound':
      return node.list.map(customStringify).join('')
    case 'list':
      return node.list.map(customStringify).join(', ')
    default:
      return parsel.stringify(node)
  }
}
