import { IFrameDocumentPostProcessorParameters } from '../../iframe-loader'

import { cssSelectorNamespaceProcessor } from './css-selector-namespace-processor'

export const POSTPROCESSOR_STYLE_ID = 'postprocessor_style_override'

type IFrameWindowContext = Window & typeof globalThis

/**
 * IFrameDocumentPostProcessor that processes all stylesheets, replacing
 * namespaced attribute CSS rules using '|' with escaped rules (i.e. '\:')
 *
 * @export
 * @param {IFrameDocumentPostProcessorParameters} parameters - processor parameters
 * @return {Promise<void>}
 */
export async function stylesheetPostProcessor(
  parameters: IFrameDocumentPostProcessorParameters,
): Promise<void> {
  const { document } = parameters

  if (!document) {
    throw new Error('The document should not be empty')
  }
  if (typeof document !== 'object') {
    throw new Error('The document should be an object')
  }

  const newRules = processStylesheets(document)
  if (newRules.length > 0) {
    writeStylesheet(document, newRules)
  }

  return Promise.resolve()
}

function processStylesheets(document: Document): string[] {
  const stylesheets = document.styleSheets
  const contentWindow = document.defaultView

  if (!stylesheets) {
    throw new Error('The collection of stylesheets should be defined')
  }

  if (!contentWindow) {
    console.warn(
      'Cannot process stylesheets. Document does not have a parent window.',
    )
    return new Array<string>()
  }

  const newRules = new Array<string>()

  // eslint-disable-next-line
  for (let i = 0; i < stylesheets.length; i++) { // nosonar
    try {
      newRules.push(...processStylesheet(stylesheets[i], contentWindow))
    } catch (ex) {
      if (ex instanceof contentWindow.DOMException) {
        if (ex.message.includes('cssRules')) {
          console.warn('Could not read cssRules due to CORS security')
        } else {
          console.error(ex)
        }
      } else {
        console.error(ex)
      }
    }
  }

  return newRules
}

function processStylesheet(
  stylesheet: CSSStyleSheet,
  iframeWindow: IFrameWindowContext,
): string[] {
  const rules = stylesheet.cssRules

  // Collect new rules to be added
  const newRules: string[] = []
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i]
    if (!(rule instanceof iframeWindow.CSSStyleRule)) {
      continue
    }
    if (!rule.cssText.startsWith(rule.selectorText)) {
      console.warn(
        'Unable to process CSS style. Rule text does not start with selector',
      )
      continue
    }

    const newSelectorStr = cssSelectorNamespaceProcessor(rule.selectorText)
    if (newSelectorStr) {
      const slicedRuleText = rule.cssText.substring(rule.selectorText.length)
      newRules.push(newSelectorStr + slicedRuleText)
    }
  }

  return newRules
}

// Upserts a style element with new CSS rules from this postprocessor step
// Note: First implementation tried to use `insertRule` on each stylesheet that
// new rules were found at, but there was something causing document stylesheets
// to get reloaded and lost the changes that were made, so we are persisting
// these new rules in this way
function writeStylesheet(document: Document, newRules: string[]) {
  const contentWindow = document.defaultView
  if (!contentWindow) {
    console.warn(
      'Cannot process stylesheets. Document does not have a parent window.',
    )
    return
  }

  const el =
    document.getElementById(POSTPROCESSOR_STYLE_ID) ??
    document.createElement('style')
  if (!el) {
    console.warn('Unable to create postprocessor stylesheet element')
    return
  }

  // Setup style element
  el.id = POSTPROCESSOR_STYLE_ID
  el.innerHTML = newRules.join('\n')

  // Append if this was a created element
  if (!el.parentElement) {
    document.head.append(el)
  }
}
