import { traverseThroughAncestors } from '../../../utils'

import type { IsContainingBlockForFixedPositionedElementCallback } from './types'
import { isContainingBlockForFixedPositionedElementCallbackImpl } from './is-containing-block-for-fixed-positioned-element'

/**
 * It will traverse element's ancestors and look for an element that matches the definition of "Containing block"
 * parent element for an element that has a CSS rule `position:fixed`.
 * https://developer.mozilla.org/en-US/docs/Web/CSS/Containing_block#identifying_the_containing_block
 *
 * @export
 * @param {HTMLElement} element - a target element the "Containing block" of which will be found.
 * @param {IsContainingBlockForFixedPositionedElementCallback} [isContainingBlockForFixedPositionedElementCallback=isContainingBlockForFixedPositionedElementCallbackImpl] - an optional
 * argument, that is a function that checks if an element matches the specification of "Containing block".
 * @return {(HTMLElement | null)} - either an element that is the "Containing block" or null if there is no one.
 * If the function yields "null" as the result, then the Viewport should be regarded as the "Containing block".
 */
export function determineFixedPositionedElementContainingBlock(
  element: HTMLElement,
  isContainingBlockForFixedPositionedElementCallback: IsContainingBlockForFixedPositionedElementCallback = isContainingBlockForFixedPositionedElementCallbackImpl,
): HTMLElement | null {
  return traverseThroughAncestors(
    element,
    isContainingBlockForFixedPositionedElementCallback,
  )
}
