import type { Resource } from '../../navigator'

import { injectAsset, injectAssetWithPreloadAsync } from './inject-asset'
import type { InjectAsset, InjectAssetAsync } from './types'

export function applyResourcesToDocument(
  resources: Resource[],
  document: Document,
  injectAssetToIFrame: InjectAsset = injectAsset,
): void {
  if (!resources) {
    return
  }

  resources.forEach((resource) => {
    injectAssetToIFrame(resource, document)
  })
}

export async function applyResourcesToDocumentAsync(
  resources: Resource[],
  document: Document,
  injectAssetToIFrame:
    | InjectAsset
    | InjectAssetAsync = injectAssetWithPreloadAsync,
): Promise<void> {
  if (!resources) {
    return
  }
  await Promise.all(
    resources.map((resource) => {
      return injectAssetToIFrame(resource, document)
    }),
  )
}

export async function applyResourcesToDocumentWithoutPreloadAsync(
  resources: Resource[],
  document: Document,
): Promise<void> {
  return await applyResourcesToDocumentAsync(resources, document, injectAsset)
}
