import { checkIfHtmlElement } from './check-if-html-element'

/**
 * Displays a copy of the image in the canvas element.
 *
 * @export
 * @param {HTMLCanvasElement} canvasElement - the canvas element where to put the copy of the image.
 * @param {ArrayBuffer} imageSource - image binary data.
 * @param {{
 *     width: number
 *     height: number
 *   }} dimensions - image and its copy size.
 * @return {Promise<void>}
 */
export async function imageToCanvas(
  canvasElement: HTMLCanvasElement,
  imageSource: ArrayBuffer,
  dimensions: {
    width: number
    height: number
  },
): Promise<void> {
  if (!checkIfHtmlElement(canvasElement)) {
    throw new Error('The canvas element should be defined')
  }
  if (!imageSource) {
    throw new Error('The image source should be an defined')
  }
  if (!dimensions) {
    throw new Error('The dimensions of the image should be defined')
  }

  const { height: imageHeight, width: imageWidth } = dimensions

  if (!imageWidth) {
    throw new Error('The width should be defined and not be a zero')
  }
  if (!imageHeight) {
    throw new Error('The heigh should be defined and not be a zero')
  }

  const context = canvasElement.getContext('2d')
  if (!context) {
    throw new Error('Failed to get 2d context on the Canvas element')
  }
  const imageBitmap = await createImageBitmap(
    new Blob([imageSource]),
    0,
    0,
    imageWidth,
    imageHeight,
  )

  context.drawImage(imageBitmap, 0, 0, imageWidth, imageHeight)
}
