import { arrayBufferToBase64, checkIfHtmlElement } from '../utils'

import { DatasetPropertyImageBase64Content } from './const'
import { SetImageData } from './types'

/**
 * Set the original image content to the dataset to use it later.
 * Clean the src of the image.
 * The original image won't be exposed on the Network tab this way.
 *
 * @param {HTMLImageElement} imgElement - an image element where to put the data.
 * @param {Blob} binaryData - the original image binary data.
 * @return {Promise<void>}
 */
export const setImageBinaryContentToDatasetAndCleanSrc: SetImageData = async function setImageBinaryContentToDatasetAndCleanSrcImpl(
  imgElement: HTMLImageElement,
  binaryData: Blob,
): Promise<void> {
  if (!checkIfHtmlElement(imgElement)) {
    throw new Error('The image should be an HTMLElement')
  }
  if (!binaryData) {
    throw new Error('The binary data should be defined')
  }

  const arrayBuffer = await binaryData.arrayBuffer()
  imgElement.removeAttribute('src')
  imgElement.removeAttribute('srcset')
  imgElement.dataset[DatasetPropertyImageBase64Content] = arrayBufferToBase64(
    arrayBuffer,
  )
}
