import { Page as PageProperty, Publication } from '@flowpub/webpub-model'

import { Location } from '../location'

import { IContentViewFactory } from './content-view/content-view-factory'
import { SpineItemView } from './spine-item-view'
import { SpineItemViewFactory } from './spine-item-view-factory'
import { SettingName, ZoomOptions, SpreadLocation } from './types'
import type {
  CancellationToken,
  WaitContentViewFitInIframeWindow,
  HandleUnloadSpineItemCallback,
} from './types'
import { waitContentViewFitInIframeWindowOrTimeout } from './utils'
import { View } from './view'
import { ViewSettings } from './view-settings'

export class PaginationInfo {
  public spineItemIndex: number
  public spineItemPageCount: number
  public pageIndex: number
  public view: SpineItemView
  public viewOffset: number
  public offsetInView: number
}

type SpreadInfo = {
  isDoublePage: boolean
  leftIndex?: number
  centerIndex?: number
  rightIndex?: number
  width?: number
}

class SpineItemViewStatus {
  public view: SpineItemView
  public viewContainer: HTMLElement
  public spineItemIndex: number
  public offset: number
  public viewSize: number
}

export interface LayoutViewDependencies {
  waitContentViewFitInIframeWindow: WaitContentViewFitInIframeWindow
}

const LayoutViewDependenciesDefaults: LayoutViewDependencies = {
  waitContentViewFitInIframeWindow: waitContentViewFitInIframeWindowOrTimeout,
}

export class LayoutView extends View {
  private spineItemViewStatus: SpineItemViewStatus[] = []
  private spineItemViewSizes: number[] = []
  private spineItemViewPageCounts: number[] = []
  private spreads: SpreadInfo[] = []

  private host: HTMLElement
  private layoutRoot: HTMLElement

  private publication: Publication

  private vs: ViewSettings
  private isViewSettingChanged = false

  private loadedContentRange: [number, number] = [0, 0]
  private paginatedRange: [number, number] = [0, 0]

  private pageWidth = 600
  private pageHeight = 800
  private isPageSizeChanged = false

  private inViewUpdate = false

  private isVertical = false

  private hasUnknownSizeSpineItemLoading = false

  public readonly isFixedLayout: boolean = false
  private zoomOption: ZoomOptions = ZoomOptions.FitByPage
  private zoomScale = 1

  private spineItemViewFactory: SpineItemViewFactory

  private readonly isRtl: boolean = false

  private numOfPagesPerSpread = 0
  private handleUnloadSpineItemCallback?: HandleUnloadSpineItemCallback

  private repaginationHandler?: () => void

  private waitContentViewFitInIframeWindow: WaitContentViewFitInIframeWindow

  public constructor(
    pub: Publication,
    vs: ViewSettings,
    cvFactory: IContentViewFactory,
    dependencies: LayoutViewDependencies = LayoutViewDependenciesDefaults,
  ) {
    super()
    this.publication = pub
    this.vs = vs
    this.initSpineItemViews()
    this.waitContentViewFitInIframeWindow =
      dependencies.waitContentViewFitInIframeWindow

    if (this.publication.metadata.presentation) {
      this.isFixedLayout =
        this.publication.metadata.presentation.layout === 'fixed'
    }

    if (this.publication.metadata.readingProgression) {
      this.isRtl = this.publication.metadata.readingProgression === 'rtl'
    }

    this.spineItemViewFactory = new SpineItemViewFactory(
      pub,
      this.isFixedLayout,
      cvFactory,
    )

    // tslint:disable-next-line:prefer-array-literal
    this.spineItemViewSizes = new Array<number>(pub.spine.length).fill(-1)
    // tslint:disable-next-line:prefer-array-literal
    this.spineItemViewPageCounts = new Array<number>(pub.spine.length).fill(-1)
  }

  public reset(): void {
    this.clearLoadedContent()
    this.paginatedRange = [0, 0]
    this.spineItemViewSizes.fill(-1)
    this.spineItemViewPageCounts.fill(-1)
  }

  public getSpineItemView(spineItemIndex: number): SpineItemView | undefined {
    for (const siv of this.spineItemViewStatus) {
      if (siv.spineItemIndex === spineItemIndex) {
        return siv.view
      }
    }

    return undefined
  }

  public getSpineItemViewOffset(spineItemIndex: number): number | undefined {
    for (const siv of this.spineItemViewStatus) {
      if (siv.spineItemIndex === spineItemIndex) {
        return siv.offset
      }
    }

    return undefined
  }

  public isSpineItemVisible(
    siIndex: number,
    viewOffset: number,
    viewportSize: number,
  ): boolean {
    const viewStatus = this.spineItemViewStatus.find(
      (status: SpineItemViewStatus) => {
        return status.spineItemIndex === siIndex
      },
    )

    if (!viewStatus) {
      return false
    }

    if (
      viewStatus.offset + viewStatus.viewSize < viewOffset ||
      viewStatus.offset > viewOffset + viewportSize
    ) {
      return false
    }

    return true
  }

  public getOffsetInSpineItemView(
    siIndex: number,
    viewOffset: number,
  ): number | undefined {
    const viewStatus = this.spineItemViewStatus.find(
      (status: SpineItemViewStatus) => {
        return status.spineItemIndex === siIndex
      },
    )

    if (!viewStatus) {
      return undefined
    }

    return viewOffset - viewStatus.offset
  }

  public findSpineItemIndexByHref(href: string): number {
    return this.publication.findSpineItemIndexByHref(href)
  }

  public isRightToLeft(): boolean {
    return this.isRtl
  }

  public setPageSize(width: number, height: number): void {
    this.pageWidth = width
    this.pageHeight = height
    if (!this.isVertical) {
      this.layoutRoot.style.height = `${this.visualPageHeight()}px`
    } else {
      this.layoutRoot.style.width = `${this.visualPageWidth()}px`
    }

    this.isPageSizeChanged = true

    if (!this.inViewUpdate) {
      this.rePaginate()
      this.isPageSizeChanged = false
    }
  }

  public getPageWidth(): number {
    return this.pageWidth
  }

  public getSpreadWidthOfSpineItem(spineItemIndex: number): number | undefined {
    for (const spread of this.spreads) {
      if (
        spread.centerIndex === spineItemIndex ||
        spread.leftIndex === spineItemIndex ||
        spread.rightIndex === spineItemIndex
      ) {
        return spread.width
      }
    }
  }

  public setNumberOfPagesPerSpread(num: number): void {
    this.numOfPagesPerSpread = num
  }

  public numberOfPagesPerSpread(): number {
    return this.numOfPagesPerSpread
  }

  public getColumnGap(): number {
    return this.vs.getSettingWithDefaultValue(SettingName.ColumnGap, 0)
  }

  public beginViewUpdate(): void {
    this.inViewUpdate = true
  }

  public endViewUpdate(): void {
    if (!this.inViewUpdate) {
      return
    }

    this.rePaginate()

    this.inViewUpdate = false
    this.isViewSettingChanged = false
    this.isPageSizeChanged = false
  }

  public updateViewSettings(): void {
    // if (viewSetting.hasOwnProperty('syntheticSpread')) {
    //   delete viewSetting.syntheticSpread;
    // }

    this.isViewSettingChanged = true

    if (!this.inViewUpdate) {
      this.rePaginate()
      this.isViewSettingChanged = false
    }
  }

  public setZoom(option: ZoomOptions, scale: number): void {
    if (!this.isFixedLayout) {
      return
    }

    if (this.zoomOption === option && this.zoomScale === scale) {
      return
    }

    this.zoomOption = option
    this.zoomScale = scale

    this.isPageSizeChanged = true
    this.rePaginate()
    this.isPageSizeChanged = false
  }

  public getZoomScale(): number {
    return this.zoomScale
  }

  public getZoomOption(): ZoomOptions {
    return this.zoomOption
  }

  public setVerticalLayout(v: boolean): void {
    this.isVertical = v
    this.spineItemViewFactory.setVerticalLayout(v)
  }

  public isVerticalLayout(): boolean {
    return this.isVertical
  }

  public render(): void {
    return
  }

  public attachToHost(host: HTMLElement): void {
    this.host = host
    this.host.appendChild(this.layoutRoot)
  }

  public containerElement(): HTMLElement {
    return this.layoutRoot
  }

  public hasMoreAfterEnd(): boolean {
    return this.nextIndexAfterEnd() < this.publication.spine.length
  }

  public hasMoreBeforeStart(): boolean {
    return this.nextIndexBeforeStart() >= 0
  }

  public getLoadedStartPostion(): number {
    return this.loadedContentRange[0]
  }

  public getLoadedEndPosition(): number {
    return this.loadedContentRange[1]
  }

  public isEmpty(): boolean {
    return this.loadedContentRange[0] === this.loadedContentRange[1]
  }

  public loadedRangeLength(): number {
    return this.loadedContentRange[1] - this.loadedContentRange[0]
  }

  public paginatedLength(): number {
    return this.paginatedRange[1] - this.paginatedRange[0]
  }

  public getPaginationInfoAtOffset(offset: number): PaginationInfo[] {
    const res: PaginationInfo[] = []
    if (
      offset < this.getLoadedStartPostion() ||
      offset > this.getLoadedEndPosition()
    ) {
      return res
    }

    for (const siv of this.spineItemViewStatus) {
      if (offset >= siv.offset && offset <= siv.offset + siv.viewSize) {
        res.push({
          spineItemIndex: siv.spineItemIndex,
          spineItemPageCount: siv.view.getTotalPageCount(),
          pageIndex: Math.floor((offset - siv.offset) / this.pageWidth),
          view: siv.view,
          viewOffset: siv.offset,
          offsetInView: offset - siv.offset,
        })
      }
    }

    return res
  }

  public async getOffsetFromLocation(
    loc: Location,
  ): Promise<number | undefined> {
    const siv = await this.getSpineItemViewStatusFromHref(loc.getHref())
    if (!siv) {
      return undefined
    }

    let inSpineItemOffset = 0
    const cfi = loc.getLocation()
    if (this.isVertical) {
      if (cfi) {
        inSpineItemOffset = siv.view.getOffsetFromCfi(cfi)
      } else {
        inSpineItemOffset = siv.view.getOffsetFromCharOffset(
          loc.getCharOffset(),
        )
      }
    } else {
      let pageIndexOffset = -1
      if (cfi) {
        pageIndexOffset = siv.view.getPageIndexOffsetFromCfi(cfi)
      } else {
        pageIndexOffset = siv.view.getPageIndexOffsetFromCharOffset(
          loc.getCharOffset(),
        )
      }

      inSpineItemOffset =
        pageIndexOffset < 0 ? 0 : pageIndexOffset * this.pageWidth
    }

    if (inSpineItemOffset < 0) {
      return undefined
    }

    return siv.offset + inSpineItemOffset
  }

  public async getOffsetFromAnchor(
    href: string,
    elementId?: string,
  ): Promise<number | undefined> {
    const siv = await this.getSpineItemViewStatusFromHref(href)
    if (!siv) {
      return undefined
    }

    let inSpineItemOffset = 0
    if (elementId) {
      if (this.isVertical) {
        inSpineItemOffset = siv.view.getOffsetFromElementId(elementId)
      } else {
        const pageIndexOffset = siv.view.getPageIndexOffsetFromElementId(
          elementId,
        )
        inSpineItemOffset =
          pageIndexOffset < 0 ? 0 : pageIndexOffset * this.pageWidth
      }
    }

    if (inSpineItemOffset < 0) {
      return undefined
    }

    return siv.offset + inSpineItemOffset
  }

  public getCfiFromAnchor(href: string, elementId: string): string | undefined {
    const siv = this.getLoadedSpineItemViewStatusFromHref(href)
    if (!siv) {
      return undefined
    }

    return siv.view.getCfiFromElementId(elementId)
  }

  public async ensureLoaded(token?: CancellationToken): Promise<void> {
    for (const siv of this.spineItemViewStatus) {
      await siv.view.ensureContentLoaded(token)
      if (token && token.isCancelled) {
        break
      }
    }
  }

  public async ensureConentLoadedAtRange(
    start: number,
    end: number,
    token?: CancellationToken,
  ): Promise<void> {
    // first try to load spine items with known size
    while (
      end > this.getLoadedEndPosition() &&
      this.hasMoreKnownSizeAfterEnd()
    ) {
      if (token && token.isCancelled) {
        break
      }
      await this.loadNewSpineItemAtEnd(token)
    }

    while (
      start < this.getLoadedStartPostion() &&
      this.hasMoreKnowSizeBeforeStart()
    ) {
      if (token && token.isCancelled) {
        break
      }
      await this.loadNewSpineItemAtStart(token)
    }

    this.updatePaginatedRange()

    while (end > this.getLoadedEndPosition() && this.hasMoreAfterEnd()) {
      if (token && token.isCancelled) {
        break
      }
      await this.loadNewSpineItemAtEnd(token)
    }

    while (start < this.getLoadedStartPostion() && this.hasMoreBeforeStart()) {
      if (token && token.isCancelled) {
        break
      }
      await this.loadNewSpineItemAtStart(token)
    }

    this.updatePaginatedRange()
  }

  public async ensureContentLoadedAtSpineItemRange(
    startIndex: number,
    endIndex: number,
    token?: CancellationToken,
  ): Promise<void> {
    if (endIndex < 0 || startIndex >= this.publication.spine.length) {
      return
    }

    let isEmpty = this.spineItemViewStatus.length === 0
    if (!isEmpty) {
      if (
        this.startViewStatus().spineItemIndex > endIndex ||
        this.endViewStatus().spineItemIndex < startIndex
      ) {
        this.clearLoadedContent()
        isEmpty = true
      }
    }

    if (isEmpty) {
      await this.loadNewSpineItemIndexAtEnd(startIndex, token)
      if (token && token.isCancelled) {
        return
      }
    }

    const existingStartIndex = this.startViewStatus().spineItemIndex
    for (let i = existingStartIndex; i > startIndex; i = i - 1) {
      await this.loadNewSpineItemAtStart(token)
      if (token && token.isCancelled) {
        return
      }
    }

    const existingEndIndex = this.endViewStatus().spineItemIndex
    for (let i = existingEndIndex; i < endIndex; i = i + 1) {
      await this.loadNewSpineItemAtEnd(token)
      if (token && token.isCancelled) {
        return
      }
    }
  }

  public adjustLoadedConentRangeToPositive(): number {
    if (this.spineItemViewStatus.length === 0) {
      return 0
    }

    const adj = this.startViewStatus().offset
    if (adj > 0) {
      return 0
    }

    this.adjustRange(adj)

    return adj
  }

  public showOnlySpineItemRange(spineItemIndex: number): void {
    let viewStatus: SpineItemViewStatus | undefined
    for (const siv of this.spineItemViewStatus) {
      if (siv.spineItemIndex === spineItemIndex) {
        viewStatus = siv
      }
    }
    if (!viewStatus) {
      return
    }

    const offset = viewStatus.offset
    this.adjustRange(offset)

    const size = viewStatus.view.getTotalSize(0)
    this.layoutRoot.style.height = `${size}px`
    this.layoutRoot.style.overflow = 'hidden'
  }

  public fixedLayoutPageSizes(
    startOffset: number,
    pagesAfterStart: number,
    pagesBeforeStart: number,
  ): [number, number][] {
    // gets start offset, end offset and height of pages:
    //  - page at "offset = start" (call it start page)
    //  - pages after start offset, numbering pagesAfterStart
    //  - pages before start offset, numbering pagesBeforeStart
    const pageRanges: [number, number][] = []
    const startPageInfo = this.getPaginationInfoAtOffset(startOffset)
    if (startPageInfo.length === 0) {
      return pageRanges
    }

    const spineItemIndex =
      startPageInfo[startPageInfo.length - 1].spineItemIndex
    const startItemIndex = spineItemIndex - pagesBeforeStart
    const endItemIndex = spineItemIndex + pagesAfterStart
    for (const vs of this.spineItemViewStatus) {
      if (
        vs.spineItemIndex >= startItemIndex &&
        vs.spineItemIndex <= endItemIndex
      ) {
        const pageSize = this.spineItemViewSizes[vs.spineItemIndex]
        const pageStart = vs.offset
        const pageEnd = pageStart + pageSize
        pageRanges.push([pageStart, pageEnd])
      }
    }

    return pageRanges
  }

  public isOnRightOfdoublePageSpread(pos: number): boolean {
    if (!this.isFixedLayout) {
      return false
    }

    const startPageInfo = this.getPaginationInfoAtOffset(pos)
    if (startPageInfo.length === 0) {
      return false
    }

    const spineItemIndex =
      startPageInfo[startPageInfo.length - 1].spineItemIndex

    for (const spread of this.spreads) {
      if (
        spread.centerIndex === spineItemIndex ||
        spread.leftIndex === spineItemIndex ||
        spread.rightIndex === spineItemIndex
      ) {
        return (
          spread.isDoublePage &&
          spread.leftIndex === spineItemIndex - 1 &&
          spread.rightIndex === spineItemIndex
        )
      }
    }

    return false
  }

  public arrangeSpreads(vpWidth: number, vpHeight: number): void {
    if (!this.isFixedLayout) {
      return
    }

    this.spreads = []
    for (let i = 0; i < this.publication.readingOrder.length; i++) {
      const spread: SpreadInfo = {
        isDoublePage: this.tryDoublePageSpread(i, vpWidth, vpHeight),
      }
      if (!spread.isDoublePage) {
        spread.centerIndex = i
        this.spreads.push(spread)
        continue
      }

      const si = this.publication.readingOrder[i]
      const prop = si.properties?.page

      // special case of the first page
      if (prop === undefined && i === 0) {
        spread.rightIndex = i
        this.spreads.push(spread)
        continue
      }

      if (prop === undefined || prop === 'left') {
        spread.leftIndex = i
        if (i + 1 < this.publication.readingOrder.length) {
          const nextIndex = i + 1
          const nextProp = this.publication.readingOrder[nextIndex]?.properties
            ?.page
          let canNextFitOnRight = nextProp === 'right'
          if (nextProp === undefined) {
            canNextFitOnRight = this.tryDoublePageSpread(
              nextIndex,
              vpWidth,
              vpHeight,
            )
          }
          if (canNextFitOnRight) {
            spread.rightIndex = nextIndex
            i++
          }
        }
      } else if (prop === 'center') {
        spread.centerIndex = i
      } else if (prop === 'right') {
        spread.rightIndex = i
      }

      this.spreads.push(spread)
    }
  }

  public removeOutOfRangeSpineItems(start: number, end: number): void {
    let newStart: number = this.loadedContentRange[1]
    let newEnd: number = this.loadedContentRange[0]
    let hasAnyRemoved = false
    for (const vs of this.spineItemViewStatus) {
      const viewEnd = vs.offset + vs.viewSize
      if (viewEnd < start || vs.offset > end) {
        vs.view.unloadSpineItem()
        if (this.layoutRoot.contains(vs.viewContainer)) {
          this.layoutRoot.removeChild(vs.viewContainer)
        }
        hasAnyRemoved = true
      } else {
        if (vs.offset < newStart) {
          newStart = vs.offset
        }
        if (viewEnd > newEnd) {
          newEnd = viewEnd
        }
      }
    }

    if (hasAnyRemoved) {
      if (newStart >= newEnd) {
        this.loadedContentRange = [0, 0]
      } else {
        this.loadedContentRange = [newStart, newEnd]
      }

      this.spineItemViewStatus = this.spineItemViewStatus.filter(
        (vs: SpineItemViewStatus) => {
          return vs.view.isSpineItemInUse()
        },
      )
    }
  }

  public onRepagination(handler: () => void): void {
    this.repaginationHandler = handler
  }

  /**
   * Set a callback function that will be invoked once the spine item
   * is unloaded.
   *
   * TODO - add "unsetUnloadSpineItemHandler".
   *
   * @param {HandleUnloadSpineItemCallback} handleUnloadSpineItemCallback
   * @memberof SpineItemView
   */
  public setUnloadSpineItemHandler(
    handleUnloadSpineItemCallback: HandleUnloadSpineItemCallback,
  ): void {
    this.handleUnloadSpineItemCallback = handleUnloadSpineItemCallback
    this.setUnloadSpineItemHandlerOnAllSpineItems()
  }

  private clearLoadedContent(): void {
    this.spineItemViewStatus.forEach((v: SpineItemViewStatus) => {
      v.view.unloadSpineItem()
      this.layoutRoot.removeChild(v.viewContainer)
    })

    this.spineItemViewStatus = []
    this.loadedContentRange = [0, 0]
  }

  private visualPageWidth(): number {
    return this.pageWidth * this.zoomScale
  }

  private visualPageHeight(): number {
    return this.pageHeight * this.zoomScale
  }

  private initSpineItemViews(): void {
    this.layoutRoot = document.createElement('div')
    this.layoutRoot.setAttribute('id', 'layout-view-root')
    this.layoutRoot.style.transform = 'translateX(0px)'
    this.layoutRoot.style.willChange = 'transform'
    // disable pinch touch gestures so the iframes could
    // reliably handle pinch without triggering zoom on
    // the host level on iOS
    // iOS 13 needs 'pan-x pan-y' to make scrolling work.
    // 'none' makes vertical scrolling stop working
    this.layoutRoot.style.touchAction = 'pan-x pan-y'
  }

  private startViewStatus(): SpineItemViewStatus {
    return this.spineItemViewStatus[0]
  }

  private endViewStatus(): SpineItemViewStatus {
    return this.spineItemViewStatus[this.spineItemViewStatus.length - 1]
  }

  private visibleViewStatus(): SpineItemViewStatus {
    let visibleVs = this.spineItemViewStatus[0]
    if (!this.getViewOffset) {
      return visibleVs
    }

    for (const vs of this.spineItemViewStatus) {
      const start = vs.offset
      const end = vs.viewSize + start
      if (this.getViewOffset() >= start && this.getViewOffset() < end) {
        visibleVs = vs
        break
      }
    }
    return visibleVs
  }

  private nextIndexAfterEnd(): number {
    let nextIndex = 0
    if (this.spineItemViewStatus.length > 0) {
      nextIndex = this.endViewStatus().spineItemIndex + 1
    }

    return nextIndex
  }

  private nextIndexBeforeStart(): number {
    let nextIndex = 0
    if (this.spineItemViewStatus.length > 0) {
      nextIndex = this.startViewStatus().spineItemIndex - 1
    }

    return nextIndex
  }

  private hasMoreKnownSizeAfterEnd(): boolean {
    const nextIndex = this.nextIndexAfterEnd()

    return (
      nextIndex < this.spineItemViewSizes.length &&
      this.spineItemViewSizes[nextIndex] > 0
    )
  }

  private hasMoreKnowSizeBeforeStart(): boolean {
    const nextIndex = this.nextIndexBeforeStart()

    return nextIndex >= 0 && this.spineItemViewSizes[nextIndex] > 0
  }

  private getViewOffset: (() => number) | undefined = undefined
  public setViewOffsetGetter(getter: () => number): void {
    this.getViewOffset = getter
  }

  private getViewportSize: (() => number) | undefined = undefined
  public setViewportSizeGetter(getter: () => number): void {
    this.getViewportSize = getter
  }

  private async paginateView(vs: SpineItemViewStatus): Promise<void> {
    if (this.isViewSettingChanged) {
      vs.view.setViewSettings(this.vs)
    }

    const outerWidth = this.getViewportSize
      ? this.getViewportSize()
      : this.host.clientWidth

    vs.view.setZoomOption(this.zoomOption)

    if (!this.isVertical || this.isFixedLayout) {
      // need to set width before calling resize so reflowable view
      // will have the correct width
      vs.viewContainer.style.width = `${this.visualPageWidth()}px`
      vs.viewContainer.style.height = `${this.visualPageHeight()}px`
    }

    vs.viewContainer.style.display = 'flex'
    vs.viewContainer.style.alignItems = 'center'

    const spineItemIndex = vs.spineItemIndex
    let spread: SpreadInfo | undefined
    let prop: PageProperty = 'center'
    for (const sp of this.spreads) {
      if (
        sp.centerIndex === spineItemIndex ||
        sp.leftIndex === spineItemIndex ||
        sp.rightIndex === spineItemIndex
      ) {
        spread = sp
        if (sp.centerIndex === spineItemIndex) {
          vs.view.getContentView().applySpreadLocation(SpreadLocation.Center)
          prop = 'center'
        } else if (sp.leftIndex === spineItemIndex) {
          vs.view.getContentView().applySpreadLocation(SpreadLocation.Left)
          prop = 'left'
        } else if (sp.rightIndex === spineItemIndex) {
          vs.view.getContentView().applySpreadLocation(SpreadLocation.Right)
          prop = 'right'
        }
      }
    }

    const isOneVisiblePageSpread =
      this.numberOfPagesPerSpread() === 1 ||
      spread?.leftIndex === undefined ||
      spread?.rightIndex === undefined
    let viewSize = isOneVisiblePageSpread ? outerWidth : outerWidth / 2
    let viewContainerSize = viewSize
    let contentJustification = 'unset'
    let leftPadding = 'unset'

    let contentSize = this.visualPageWidth()
    if (spread && this.numberOfPagesPerSpread() !== 0) {
      contentSize = spread.isDoublePage ? outerWidth / 2 : outerWidth
    }
    vs.view.resize(contentSize, this.visualPageHeight())

    let spreadWidth = vs.view.getPageSize(this.pageWidth) * 2
    // numberofpagesperspread will be zero in SpreadMode.Freeform
    if (!this.isFixedLayout || this.numberOfPagesPerSpread() === 0) {
      viewSize = vs.view.getTotalSize(this.pageWidth)
      viewContainerSize = this.visualPageWidth()
    } else if (isOneVisiblePageSpread) {
      if (prop === 'center') {
        contentJustification = 'center'
        spreadWidth = vs.view.getPageSize(this.pageWidth)
      } else {
        if (prop === 'left') {
          const padding = outerWidth / 2 - vs.view.getPageSize(this.pageWidth)
          leftPadding = `${padding}px`
        } else if (prop === 'right') {
          leftPadding = `${outerWidth / 2}px`
        }
      }
    } else if (!isOneVisiblePageSpread) {
      if (prop === 'left') {
        contentJustification = 'flex-end'
      } else if (prop === 'right') {
        contentJustification = 'unset'
      }
    }

    if (spread) {
      spread.width = spreadWidth
    }
    vs.viewSize = viewSize
    vs.viewContainer.style.width = `${viewContainerSize}px`
    vs.viewContainer.style.justifyContent = contentJustification
    vs.viewContainer.style.paddingLeft = leftPadding

    this.spineItemViewSizes[vs.spineItemIndex] = vs.viewSize
    this.spineItemViewPageCounts[
      vs.spineItemIndex
    ] = vs.view.getTotalPageCount()
  }

  private rePaginate(): void {
    this.spineItemViewSizes.fill(-1)

    if (this.spineItemViewStatus.length === 0) {
      return
    }

    const visibleViewStatus = this.visibleViewStatus()
    let offset = visibleViewStatus.offset
    const indexOfVisibleViewStatus = this.spineItemViewStatus.indexOf(
      visibleViewStatus,
    )
    for (let i = indexOfVisibleViewStatus - 1; i >= 0; i = i - 1) {
      const vs = this.spineItemViewStatus[i]
      this.paginateView(vs)
      offset -= vs.viewSize
      vs.offset = offset
      this.postionSpineItemView(vs)
    }

    this.loadedContentRange[0] = this.paginatedRange[0] = offset

    offset = visibleViewStatus.offset
    for (
      let i = indexOfVisibleViewStatus;
      i < this.spineItemViewStatus.length;
      i = i + 1
    ) {
      const vs = this.spineItemViewStatus[i]
      this.paginateView(vs)
      vs.offset = offset
      offset += vs.viewSize
      this.postionSpineItemView(vs)
    }

    this.loadedContentRange[1] = this.paginatedRange[1] = offset

    this.updatePaginatedRange()

    this.repaginationHandler && this.repaginationHandler()
  }

  private updatePaginatedRange(): void {
    this.paginatedRange[0] = Math.min(
      this.paginatedRange[0],
      this.loadedContentRange[0],
    )
    this.paginatedRange[1] = Math.max(
      this.paginatedRange[1],
      this.loadedContentRange[1],
    )

    if (this.isVertical) {
      this.layoutRoot.style.height = `${this.paginatedLength()}px`
    } else {
      this.layoutRoot.style.width = `${this.paginatedLength()}px`
    }
  }

  private async loadNewSpineItemAtEnd(
    token?: CancellationToken,
  ): Promise<void> {
    let newSpineItemIndex: number

    if (this.spineItemViewStatus.length === 0) {
      newSpineItemIndex = 0
    } else {
      newSpineItemIndex = this.endViewStatus().spineItemIndex + 1
    }

    if (newSpineItemIndex >= this.publication.spine.length) {
      return
    }

    await this.loadNewSpineItemIndexAtEnd(newSpineItemIndex, token)
  }

  private async loadNewSpineItemIndexAtEnd(
    index: number,
    token?: CancellationToken,
  ): Promise<void> {
    const newViewStatus = await this.loadNewSpineItem(index, token)
    if (!newViewStatus) {
      return
    }

    newViewStatus.offset =
      this.spineItemViewStatus.length === 0
        ? 0
        : this.spineItemViewStatus[0].offset
    this.spineItemViewStatus.forEach((vs: SpineItemViewStatus) => {
      newViewStatus.offset += vs.viewSize
    })
    this.addNewViewStatus(newViewStatus)

    this.loadedContentRange[1] = newViewStatus.offset + newViewStatus.viewSize

    this.postionSpineItemView(newViewStatus)
  }

  private async loadNewSpineItemAtStart(
    token?: CancellationToken,
  ): Promise<void> {
    let newSpineItemIndex: number

    if (this.spineItemViewStatus.length === 0) {
      newSpineItemIndex = 0
    } else {
      newSpineItemIndex = this.startViewStatus().spineItemIndex - 1
    }

    if (newSpineItemIndex < 0) {
      return
    }

    await this.loadNewSpineItemIndexAtStart(newSpineItemIndex, token)
  }

  private async loadNewSpineItemIndexAtStart(
    index: number,
    token?: CancellationToken,
  ): Promise<void> {
    const newViewStatus = await this.loadNewSpineItem(index, token)
    if (!newViewStatus) {
      return
    }

    newViewStatus.offset =
      this.spineItemViewStatus.length === 0
        ? 0
        : this.spineItemViewStatus[0].offset
    newViewStatus.offset -= newViewStatus.viewSize

    this.addNewViewStatus(newViewStatus)

    this.loadedContentRange[0] = newViewStatus.offset

    this.postionSpineItemView(newViewStatus)
  }

  private async loadNewSpineItem(
    index: number,
    token?: CancellationToken,
  ): Promise<SpineItemViewStatus | undefined> {
    if (token && token.isCancelled) {
      return undefined
    }
    const [spineItemView, spineItemViewContainer]: [
      SpineItemView,
      HTMLElement,
    ] = this.spineItemViewFactory.createSpineItemView(
      this.pageWidth,
      this.pageHeight,
    )

    spineItemView.hide()

    spineItemViewContainer.setAttribute('id', `spine-item-view-${index}`)

    this.layoutRoot.appendChild(spineItemViewContainer)

    let viewLength = 0
    if (this.spineItemViewSizes[index] > 0) {
      viewLength = this.spineItemViewSizes[index]
      spineItemView.setTotalPageCount(this.spineItemViewPageCounts[index])
      await spineItemView.loadSpineItem(
        this.publication.spine[index],
        this.vs,
        token,
      )
      this.onSpineItemLoaded(spineItemView)
      const sv = {
        offset: 0,
        viewContainer: spineItemViewContainer,
        spineItemIndex: index,
        view: spineItemView,
        viewSize: viewLength,
      }
      this.paginateView(sv)
      await this.waitViewGetAdjustedFirstTimeAndRepaginate(spineItemView)
    } else {
      this.hasUnknownSizeSpineItemLoading = true
      await spineItemView.loadSpineItem(
        this.publication.spine[index],
        this.vs,
        token,
      )
      this.hasUnknownSizeSpineItemLoading = false

      if (token && token.isCancelled) {
        this.layoutRoot.removeChild(spineItemViewContainer)
      } else {
        this.onSpineItemLoaded(spineItemView)
        viewLength = spineItemView.getTotalSize(this.pageWidth)
        this.spineItemViewSizes[index] = viewLength
        this.spineItemViewPageCounts[index] = spineItemView.getTotalPageCount()
        await this.waitViewGetAdjustedFirstTimeAndRepaginate(spineItemView)
      }
    }

    if (token && token.isCancelled) {
      return undefined
    }

    const sv = {
      offset: 0,
      viewContainer: spineItemViewContainer,
      spineItemIndex: index,
      view: spineItemView,
      viewSize: viewLength,
    }

    this.paginateView(sv)

    return sv
  }

  private async waitViewGetAdjustedFirstTimeAndRepaginate(
    spineItemView: SpineItemView,
  ): Promise<void> {
    await this.waitContentViewFitInIframeWindow(spineItemView)
    this.rePaginate()
  }

  private onSpineItemLoaded(siv: SpineItemView): void {
    if (siv.fixedLayout()) {
      siv.resizeFixedLayoutPage(
        this.zoomOption,
        this.visualPageWidth(),
        this.visualPageHeight(),
      )
    }
    this.setEventHandlersOnSpineItemViewItem(siv)
  }

  private setUnloadSpineItemHandlerOnSpineItemView(siv: SpineItemView): void {
    const handleUnloadSpineItemCallback = this.handleUnloadSpineItemCallback
    if (handleUnloadSpineItemCallback) {
      siv.setUnloadSpineItemHandler(handleUnloadSpineItemCallback)
    }
  }

  private setEventHandlersOnSpineItemViewItem(siv: SpineItemView): void {
    this.setUnloadSpineItemHandlerOnSpineItemView(siv)
  }

  private setUnloadSpineItemHandlerOnAllSpineItems() {
    for (const siv of this.spineItemViewStatus) {
      this.setUnloadSpineItemHandlerOnSpineItemView(siv.view)
    }
  }

  private postionSpineItemView(viewStatus: SpineItemViewStatus): void {
    let transformString: string
    if (this.isVertical) {
      transformString = `translateY(${viewStatus.offset}px)`
    } else {
      if (this.isRtl) {
        const offset = -viewStatus.offset - viewStatus.viewSize
        transformString = `translateX(${offset}px)`
      } else {
        transformString = `translateX(${viewStatus.offset}px)`
      }
    }

    viewStatus.viewContainer.style.transform = transformString
    viewStatus.view.show()
  }

  private addNewViewStatus(vs: SpineItemViewStatus): void {
    this.spineItemViewStatus.push(vs)
    this.spineItemViewStatus.sort(
      (a: SpineItemViewStatus, b: SpineItemViewStatus) => {
        return a.offset - b.offset
      },
    )
  }

  private async getSpineItemViewStatusFromHref(
    href: string,
  ): Promise<SpineItemViewStatus | undefined> {
    let retSiv: SpineItemViewStatus | undefined
    const siIndex = this.findSpineItemIndexByHref(href)
    for (const siv of this.spineItemViewStatus) {
      if (siIndex === siv.spineItemIndex) {
        await siv.view.ensureContentLoaded()
        retSiv = siv
      }
    }

    return retSiv
  }

  private getLoadedSpineItemViewStatusFromHref(
    href: string,
  ): SpineItemViewStatus | undefined {
    let retSiv: SpineItemViewStatus | undefined
    const siIndex = this.findSpineItemIndexByHref(href)
    for (const siv of this.spineItemViewStatus) {
      if (siIndex === siv.spineItemIndex) {
        if (siv.view.isContentLoaded()) {
          retSiv = siv
        } else {
          break
        }
      }
    }

    return retSiv
  }

  private adjustRange(adj: number): void {
    for (const vs of this.spineItemViewStatus) {
      vs.offset -= adj
      this.postionSpineItemView(vs)
    }

    this.loadedContentRange[0] -= adj
    this.loadedContentRange[1] -= adj
    this.paginatedRange[0] -= adj
    this.paginatedRange[1] -= adj
  }

  private tryDoublePageSpread(
    spineItemIndex: number,
    viewportWidth: number,
    viewportHeight: number,
  ): boolean {
    if (this.numOfPagesPerSpread === 2) {
      return true
    } else if (
      this.numOfPagesPerSpread === 1 ||
      this.numOfPagesPerSpread === 0
    ) {
      return false
    }

    const si = this.publication.readingOrder[spineItemIndex]

    const metaPageWidth = si.width === undefined ? 612 : si.width
    const metaPageHeight = si.height === undefined ? 792 : si.height

    const onePageScale = Math.min(
      viewportWidth / metaPageWidth,
      viewportHeight / metaPageHeight,
    )
    const twoPageScale = Math.min(
      viewportWidth / (2 * metaPageWidth),
      viewportHeight / metaPageHeight,
    )

    return twoPageScale >= onePageScale
  }
}
