import { applyToStyleDeclaration } from '../../utils/css-rules'

import { AnimationProperties, CSSRules } from './types'
import { applyCssRulesToNonInteractiveElementStyle } from './utils'

type AddContainerOptions = {
  needToAttach: boolean
}

const AddContainerOptionsDefault: AddContainerOptions = {
  needToAttach: true,
}

const StylesForClipContainer: Partial<CSSStyleDeclaration> = {
  position: 'absolute',
  height: '100%',
  overflow: 'hidden',
  margin: '',
  left: '0',
  right: '0',
  top: '0',
  bottom: '0',
  zIndex: '99',
}

function createClipContainerForTransitioningContainersLayer(): HTMLElement {
  const clipContainerForTransitioningContainersLayer = document.createElement(
    'div',
  )
  const clipContainerStyle = clipContainerForTransitioningContainersLayer.style

  Object.assign(clipContainerStyle, StylesForClipContainer)
  applyCssRulesToNonInteractiveElementStyle(clipContainerStyle)
  return clipContainerForTransitioningContainersLayer
}

function applyAnimationPropertiesForElement(
  element: HTMLElement,
  animationProperties: Partial<AnimationProperties>,
): void {
  const resultedAnimationProperties = {
    ...animationProperties,
  }
  const allowedProps: { [key: string]: string } = {
    transitionProperty: 'transition-property',
    transitionDuration: 'transition-duration',
    transitionTimingFunction: 'transition-timing-function',
    transitionDelay: 'transition-delay',
  }
  const allowedPropsList = Object.keys(allowedProps)
  const elementStyle = element.style

  // Loop over object that was passed in
  for (const key of Object.keys(resultedAnimationProperties)) {
    if (!allowedPropsList.includes(key)) {
      delete resultedAnimationProperties[
        key as keyof typeof resultedAnimationProperties
      ]
      continue
    }

    // Get name of CSS Property for object key
    const CSSPropertyKey = allowedProps[key]

    // Get value of CSS Property from animationProperties object or blankOptions
    const CSSPropertyValue =
      resultedAnimationProperties[
        key as keyof typeof resultedAnimationProperties
      ]

    // Apply changes to layout root DOM element
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    if (!CSSPropertyValue) {
      elementStyle.setProperty(CSSPropertyKey, '')
    } else {
      elementStyle.setProperty(CSSPropertyKey, CSSPropertyValue as string)
    }
  }
}

export class ContainersLayer {
  private mainHost: HTMLElement | null = null

  private animationProperties: Partial<AnimationProperties> = {}

  private clipContainerForContainersLayer: HTMLElement

  private containers: Set<HTMLElement> = new Set()

  constructor() {
    this.createAndSetClipContainer()
  }

  public attachToHost(host: HTMLElement): void {
    const currentHostElement = this.mainHost

    if (currentHostElement) {
      this.removeClipContainerChildFromHost(currentHostElement)
    }
    this.mainHost = host
    this.handleNewHost(host)
  }

  // TODO - add "remove container" method
  public addContainer(
    containerElement: HTMLElement,
    options: AddContainerOptions = AddContainerOptionsDefault,
  ): void {
    const { needToAttach } = options

    this.applyCurrentAnimationPropertiesForElement(containerElement)
    if (this.containers.has(containerElement)) {
      return
    }
    if (needToAttach) {
      this.clipContainerForContainersLayer.appendChild(containerElement)
    }
    this.containers.add(containerElement)
  }

  public updateAnimationProps(
    animationProperties: Partial<AnimationProperties>,
  ): void {
    this.animationProperties = {
      ...animationProperties,
    }
    this.applyCurrentAnimationPropertiesToAllContainers()
  }

  public applyCssPropsToContainers(cssStyle: CSSRules): void {
    this.applyCssRulesToAllContainers(cssStyle)
  }

  public applyCssPropsToClipper(cssStyle: CSSRules): void {
    applyToStyleDeclaration(
      this.clipContainerForContainersLayer.style,
      cssStyle,
    )
  }

  public addTransitionEndOnceCallback(transitionEndCallback: () => void): void {
    const containerElementOrNull: HTMLElement | null = this.mainHost

    if (!containerElementOrNull) {
      throw new Error('Container is not defined')
    }

    // eslint-disable-next-line prefer-const
    let timerBeforeAnimationStart: ReturnType<typeof setTimeout> | undefined
    const clearAnimationStartListeners = (): void => {
      containerElementOrNull.removeEventListener(
        'transitionstart',
        handleAnimationStart,
      )
      containerElementOrNull.removeEventListener(
        'animationstart',
        handleAnimationStart,
      )
    }
    const clearTimerBeforeAnimationStart = (): void => {
      timerBeforeAnimationStart && clearTimeout(timerBeforeAnimationStart)
    }
    const handleAnimationStart = (): void => {
      // if animation has started just clear the timer and wait till it's finish
      clearTimerBeforeAnimationStart()
      clearAnimationStartListeners()
    }
    const handleAnimationEnded = (): void => {
      clearTimerBeforeAnimationStart()
      clearAnimationStartListeners()
      containerElementOrNull.removeEventListener(
        'transitionend',
        handleAnimationEnded,
      )
      containerElementOrNull.removeEventListener(
        'transitioncancel',
        handleAnimationEnded,
      )
      containerElementOrNull.removeEventListener(
        'animationend',
        handleAnimationEnded,
      )
      containerElementOrNull.removeEventListener(
        'animationcancel',
        handleAnimationEnded,
      )
      transitionEndCallback()
    }

    containerElementOrNull.addEventListener(
      'transitionend',
      handleAnimationEnded,
    )
    containerElementOrNull.removeEventListener(
      'transitioncancel',
      handleAnimationEnded,
    )
    containerElementOrNull.addEventListener(
      'animationend',
      handleAnimationEnded,
    )
    containerElementOrNull.addEventListener(
      'animationcancel',
      handleAnimationEnded,
    )

    // if animation won't start in the next 100ms then call handleAnimationEnded
    timerBeforeAnimationStart = setTimeout(handleAnimationEnded, 100)

    // waiting for the animation start
    containerElementOrNull.addEventListener(
      'transitionstart',
      handleAnimationStart,
    )
    containerElementOrNull.addEventListener(
      'animationstart',
      handleAnimationStart,
    )
  }

  protected getAnimationProperties(): Partial<AnimationProperties> {
    return this.animationProperties
  }

  protected createAndSetClipContainer(): void {
    const clipContainerForTransitioningContainersLayer = createClipContainerForTransitioningContainersLayer()
    this.clipContainerForContainersLayer = clipContainerForTransitioningContainersLayer
  }

  protected handleNewHost(host: HTMLElement) {
    host.appendChild(this.clipContainerForContainersLayer)
  }

  protected removeClipContainerChildFromHost(host: HTMLElement): void {
    host.removeChild(this.clipContainerForContainersLayer)
  }

  protected applyAnimationPropertiesToHTMLElement(
    container: HTMLElement,
    animationProperties: Partial<AnimationProperties>,
  ): void {
    applyAnimationPropertiesForElement(container, animationProperties)
  }

  protected applyCssRulesToHTMLElement(
    container: HTMLElement,
    cssRules: CSSRules,
  ): void {
    applyToStyleDeclaration(container.style, cssRules)
  }

  protected callOnEachContainer(
    callback: (container: HTMLElement) => void,
  ): void {
    this.containers.forEach(callback)
  }

  protected applyCssRulesToAllContainers(cssRules: CSSRules): void {
    this.callOnEachContainer((container: HTMLElement): void => {
      this.applyCssRulesToHTMLElement(container, cssRules)
    })
  }

  protected applyCurrentAnimationPropertiesToAllContainers(): void {
    this.callOnEachContainer(this.applyCurrentAnimationPropertiesForElement)
  }

  private applyCurrentAnimationPropertiesForElement = (
    containerElement: HTMLElement,
  ): void => {
    this.applyAnimationPropertiesToHTMLElement(
      containerElement,
      this.getAnimationProperties(),
    )
  }
}
