import { checkIfImageIsCopiedToCanvas } from '../iframe-document-postprocessor'
import { findImageCopyElement } from '../iframe-document-postprocessor/utils'
import type { OriginalImageElementCopy } from '../types'

import type { ImageCopyGetter, ImageCopyGetterArgument } from './types'

export const imageCopyGetter: ImageCopyGetter = function imageCopyGetterImpl(
  parameters: ImageCopyGetterArgument,
): OriginalImageElementCopy | undefined {
  const { originalImage } = parameters

  if (!originalImage) {
    return undefined
  }
  if (!checkIfImageIsCopiedToCanvas(originalImage)) {
    return undefined
  }

  return findImageCopyElement(originalImage)
}
