import { XHTMLParser } from '../types'

import { HTMLContentType, SVGContentType } from './const'

/**
 * A parser of XML/HTML markup, that solves the issue
 * with parsing a code containing self-closing tags into
 * a valid instance of HTMLDocument.
 */
export const xhtmlToHTMLDocumentParser: XHTMLParser = {
  /**
   * Parses XML or HTML markup to HTMLDocument.
   *
   * @param {string} xmlOrHTMLCode - a string with a markup
   * @param {DOMParserSupportedType} contentType - a mime type supported by the DOMParser
   * @return {HTMLDocument} - the document
   */
  parseFromString(
    xmlOrHTMLCode: string,
    contentType: DOMParserSupportedType,
  ): HTMLDocument {
    const domParser = new DOMParser()
    if (contentType === SVGContentType) {
      throw new Error(`"${contentType}" type is not supported`)
    }
    if (contentType === HTMLContentType) {
      return domParser.parseFromString(xmlOrHTMLCode, contentType)
    }
    const xmlDoc: XMLDocument = domParser.parseFromString(
      xmlOrHTMLCode,
      contentType,
    )
    const outerHTMLCode = xmlDoc.documentElement.outerHTML
    if (!outerHTMLCode) {
      throw new Error('Failed to parse the xhtml code')
    }
    const htmlDoc = domParser.parseFromString(outerHTMLCode, HTMLContentType)
    if (!(htmlDoc instanceof HTMLDocument)) {
      throw new Error(
        `Failed to parse the code to an HTMLDocument. The class of the resulted document is ${htmlDoc.constructor.name}`,
      )
    }
    return htmlDoc
  },
}
