import type { OriginalImageElement } from '../../types'
import { ImageClassNameCanvasWithImgContent } from '../images-postprocessor/const'

/**
 * Get the sibling canvas element of the image element
 */
export function findImageCopyElement(
  imgElement: OriginalImageElement,
): HTMLCanvasElement | undefined {
  const imageSibling = imgElement.nextElementSibling
  if (
    !imageSibling ||
    imageSibling.tagName !== 'CANVAS' ||
    !imageSibling.classList.contains(ImageClassNameCanvasWithImgContent)
  ) {
    return
  }
  return imageSibling as HTMLCanvasElement
}
