import { CreateImageURLForContent } from './types'

/**
 * Preserves the image size, but fills in the entire image with
 * white color in order to not make its content exposed and returns
 * the url of the final white rectangle.
 *
 * @param {ArrayBuffer} imageBinaryContent - source data of the original image
 * @return {Promise<string>} - the url of the white rectangle image
 */
export const fillImageRectangleWithColorAndReturnURL: CreateImageURLForContent = async function getWhiteRectangleUrlImpl(
  imageBinaryContent: ArrayBuffer,
): Promise<string> {
  if (!imageBinaryContent) {
    throw new Error('Image content should be an defined')
  }
  const imageBitmap = await createImageBitmap(new Blob([imageBinaryContent]), {
    premultiplyAlpha: 'premultiply',
    resizeQuality: 'pixelated',
  })
  const imageWidth = imageBitmap.width
  const imageHeight = imageBitmap.height
  const canvas = document.createElement('canvas')
  canvas.width = imageWidth
  canvas.height = imageHeight

  const ctx = canvas.getContext('2d')
  if (!ctx) {
    throw new Error('Failed to create 2d context on Canvas element')
  }
  ctx.drawImage(imageBitmap, 0, 0, imageWidth, imageHeight)
  ctx.fillStyle = 'white'
  ctx.fillRect(0, 0, imageWidth, imageHeight)
  return canvas.toDataURL('image/jpeg', 0.1)
}
