import { Rect } from '../cfi/rect'
import { SettingName } from '../types'
import { ViewSettings } from '../view-settings'

import { R2ContentView } from './r2-content-view'
import { GetCfiOptions } from './content-view'

export class R2MultiPageContentView extends R2ContentView {
  private hostWidth: number
  private hostHeight: number

  public render(): void {
    this.iframeContainer = document.createElement('div')
    this.iframe = document.createElement('iframe')

    this.iframeContainer.appendChild(this.iframe)
    this.iframeContainer.style.position = 'absolute'

    this.host.appendChild(this.iframeContainer)

    this.setupIframe()

    this.useReadiumCss = true
  }

  public setViewSettings(viewSetting: ViewSettings): void {
    super.setViewSettings(viewSetting)
    this.paginate()
  }

  public getOffsetFromCfi(cfi: string): number {
    const offset = this.cfiNavLogic.getOffsetByCfi(cfi)
    if (offset === null) {
      return -1
    }

    return offset[0]
  }

  public getOffsetFromElementId(cfi: string): number {
    const offset = this.cfiNavLogic.getOffsetFromElementId(cfi)
    if (offset === null) {
      return -1
    }

    return offset[0]
  }

  public getPageIndexOffsetFromCfi(cfi: string): number {
    const offset = this.cfiNavLogic.getOffsetByCfi(cfi)
    if (offset === null) {
      return -1
    }

    return Math.floor(offset[0] / this.hostWidth)
  }

  public getPageIndexOffsetFromElementId(elementId: string): number {
    const offset = this.cfiNavLogic.getOffsetFromElementId(elementId)
    if (offset === null) {
      return -1
    }

    return Math.floor(offset[0] / this.hostWidth)
  }

  public getOffsetFromCharOffset(charOffset: number): number {
    const offset = this.charOffsetNavLogic.getOffsetByCharOffset(charOffset)
    if (offset === null) {
      return -1
    }

    return offset[0]
  }

  public getPageIndexOffsetFromCharOffset(charOffset: number): number {
    const offset = this.charOffsetNavLogic.getOffsetByCharOffset(charOffset)
    if (offset === null) {
      return -1
    }

    return Math.floor(offset[0] / this.hostWidth)
  }

  public getContentViewVerticalOffset(): number {
    // whole vertical space of the viewport used in reflowable views
    return 0
  }

  public getCfi(
    offsetMain: number,
    offset2nd: number,
    backward: boolean,
    options?: GetCfiOptions,
  ): string {
    const recalcLeftBasedOnDirection =
      options?.recalcLeftBasedOnDirection === undefined
        ? true
        : options.recalcLeftBasedOnDirection

    const left =
      recalcLeftBasedOnDirection && backward
        ? offsetMain - this.hostWidth
        : offsetMain
    const right = left + this.hostWidth
    const bottom = offset2nd + this.hostHeight
    const cfi = this.cfiNavLogic.getFirstVisibleCfi(
      new Rect(left, offset2nd, right, bottom),
      backward,
    )

    return cfi ? cfi : ''
  }

  public onResize(): void {
    this.paginate()
  }

  private preventDefault(e: Event) {
    e.preventDefault()
  }

  protected onIframeLoaded(success: boolean): void {
    const epubContentDocument = this.iframe.contentDocument
    if (epubContentDocument) {
      epubContentDocument.addEventListener(
        'wheel',
        function (event) {
          event.preventDefault()
        },
        { passive: false },
      )

      // prevents pinch zooming whole website on macOS safari
      epubContentDocument.addEventListener('gesturestart', this.preventDefault)
      epubContentDocument.addEventListener('gesturechange', this.preventDefault)
      epubContentDocument.addEventListener('gestureend', this.preventDefault)
      epubContentDocument.addEventListener('contextmenu', this.preventDefault)

      // prevent default browser action for assistive selection shortcut
      epubContentDocument.addEventListener('keydown', function (
        e: KeyboardEvent,
      ) {
        if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
          e.preventDefault()
        }
      })

      this.ePubHtml = epubContentDocument.querySelector('html')
      if (this.ePubHtml) {
        this.ePubHtml.style.touchAction = 'none'
        this.ePubBody = this.ePubHtml.querySelector('body')
        if (this.ePubBody) {
          this.ePubBody.style.touchAction = 'none'
        }
      }
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const anyDoc = epubContentDocument as any
    anyDoc.fonts.ready.then(() => {
      this.setViewSettings(this.vs)

      this.showIFrame()
      super.onIframeLoaded(success)
      this.cfiNavLogic.setColumnSize(this.hostWidth, this.hostHeight)
    })
  }

  private paginate(): void {
    if (!this.ePubHtml || !this.ePubBody) {
      return
    }

    const hostSize = this.getHostSize()
    if (hostSize === null) {
      return
    }

    this.hostWidth = hostSize[0]
    this.hostHeight = hostSize[1]

    if (this.cfiNavLogic) {
      this.cfiNavLogic.setColumnSize(this.hostWidth, this.hostHeight)
    }

    // Need to set the iframe width to default value
    // so resize can work properly
    this.iframe.width = '100%'
    this.iframe.style.height = `${this.hostHeight}px`

    this.ePubHtml.style.height = `${this.hostHeight}px`

    const gapValue = this.vs.getSetting<number>(SettingName.ColumnGap)
    const columnGap = gapValue === undefined ? 0 : gapValue
    const columnWidth = this.hostWidth - columnGap
    const edgeMargin = columnGap / 2

    // Using padding instead of left/right of iframe will enable us
    // to render additional content on the page edage margin, and
    // it also can improve visible element check accuracy
    this.ePubHtml.style.margin = '0px'
    this.ePubHtml.style.padding = `0px ${edgeMargin}px 0px ${edgeMargin}px`
    this.ePubHtml.style.border = '0px'

    this.ePubBody.style.margin = '0px'
    this.ePubBody.style.padding = `0px`

    let epubHtmlWidth = columnWidth
    const htmlStyles = getComputedStyle(this.ePubHtml)
    // if the box-sizing is 'border-box', the width will include padding,
    // so the padding should be added into width value to make sure
    // column width remain the same
    if (htmlStyles.boxSizing === 'border-box') {
      epubHtmlWidth = this.hostWidth // columnWidth + edgeMargin * 2
    }

    // Have to set width to make Firefox paginate correctly
    this.ePubHtml.style.width = `${epubHtmlWidth}px`
    this.ePubHtml.style.columnWidth = `${columnWidth}px`
    this.ePubHtml.style.columnGap = `${columnGap}px`
    this.ePubHtml.style.columnCount = 'auto'
    this.ePubHtml.style.columnFill = 'auto'
    this.ePubHtml.style.overflow = 'hidden'

    // scrollWidth will round the value to an integer
    // so add 1 px to workaround possible rounding issue
    const fullWidth = this.ePubHtml.scrollWidth + 1

    this.iframe.width = `${fullWidth}px`

    this.spineItemPgCount = Math.round((fullWidth + columnGap) / this.hostWidth)
  }
}
