import type { ElementOffset } from '../../types'

import { determineFixedPositionedElementContainingBlock } from './determine-fixed-positioned-element-containing-block'
import { getTallestClientRect } from './get-tallest-client-rect'

/**
 * Yields the offset of an element having position set to 'fixed' that should be
 * applied to it to position it to the point specified by the second argument.
 * Top left should be returned with border and padding taking into
 * account.
 * The same coordinates as described in
 * https://developer.mozilla.org/en-US/docs/Web/API/Element/getBoundingClientRect#return_value
 *
 * @export
 * @param {HTMLElement} element - an element that has 'position: fixed' CSS rule.
 * @param {ElementOffset | null} targetOffsetRelativeToViewport - the desired offsets define the element position
 * in relation to top/left corner of the viewport.
 * If the value is "null" the element is not visible on the current screen.
 * @return {ElementOffset | null} - the offset that should be applied via the element styles
 * as follows '{ top, left }'.
 * If the value is "null" the element is not visible.
 */
export function calculateFixedPositionedElementBorderBoxCoordinates(
  element: HTMLElement,
  targetOffsetRelativeToViewport: ElementOffset | null,
): ElementOffset | null {
  if (!element) {
    throw new Error('The "element" is not defined')
  }
  if (targetOffsetRelativeToViewport === null) {
    return null
  }
  if (!targetOffsetRelativeToViewport) {
    throw new Error('The "targetOffsetRelativeToViewport" is not defined')
  }

  const elementContainingBlockOrNull = determineFixedPositionedElementContainingBlock(
    element,
  )

  if (!elementContainingBlockOrNull) {
    // null means that the element has Viewport as its containing block.
    return targetOffsetRelativeToViewport
  }

  const offsetContainingBlockRelativeToViewport: DOMRect | null = getTallestClientRect(
    elementContainingBlockOrNull,
  )

  if (!offsetContainingBlockRelativeToViewport) {
    console.warn(
      'Failed to get the coordinates of the image containing block element',
    )
    // if the root parent is not visible
    return null
  }

  // rounding is necessary to avoid known issues with math done on too small numbers
  const targetTopOffset: number =
    Math.floor(targetOffsetRelativeToViewport.top) -
    Math.floor(offsetContainingBlockRelativeToViewport.top)
  const targetLeftOffset: number =
    Math.floor(targetOffsetRelativeToViewport.left) -
    Math.floor(offsetContainingBlockRelativeToViewport.left)
  return {
    top: targetTopOffset,
    left: targetLeftOffset,
  }
}
