import { Location } from '../location'
import {
  PageLabelInfoWithPosition,
  PageLabelVisibilityHandler,
  PageLabelVisibilityHandlerTypeName,
} from '../types'
import { applyToStyleDeclaration } from '../../utils/css-rules'

import { IContentView } from './content-view/content-view'
import { LayoutView, PaginationInfo } from './layout-view'
import {
  PageLabelContentContainerOffsets,
  PageLabelRendererPageLayoutParameters,
} from './page-labels-renderer'
import { SpineItemView } from './spine-item-view'
import { CancellationToken } from './types'
import type {
  AnimationProperties,
  VisibleRangeUpdate,
  CSSRules,
  PageLabelManagerEventEmitter,
  HandleUnloadSpineItemCallback,
} from './types'
import { ContainersLayer } from './containers-layer'
import { PageLabelsView } from './page-labels-view'
import {
  getContainerOffsetTopByRect,
  getContainerOffsetLeftByRect,
} from './utils'
import { ViewportClipperElementId } from './const'

type VisiblePagesReadyCallbackType = (cv: IContentView) => void

export enum ScrollMode {
  None,
  Publication,
  SpineItem,
}

export enum SnapDirection {
  Auto,
  Next,
  Prev,
}

// TODO - we can add a UX setting for this value
const MAX_TIMEOUT_FOR_VIEWPORT_TRANSITION_END_MS = 20000

export class Viewport {
  private bookView: LayoutView

  private viewportSize: number
  private viewportSize2nd: number
  private prefetchPercent = 0

  private visibleViewportSize = 0

  private viewOffset: number

  private startPos?: PaginationInfo
  private endPos?: PaginationInfo

  private root: HTMLElement
  private contentContainer: HTMLElement
  private clipContainer: HTMLElement

  private scrollRequestToken?: CancellationToken

  private scrollMode: ScrollMode = ScrollMode.None

  private scrollFromInternal = false

  private visiblePagesLoadingCallbacks: Array<() => void> = []
  private visiblePagesReadyCallbacks: VisiblePagesReadyCallbackType[] = []

  private locationChangedCallbacks: Function[] = []

  private zoomScale = 1

  private containersLayer: ContainersLayer

  private pageLabelsView: PageLabelsView

  private bookMargins = 0
  private verticalPadding = 0

  constructor(root: HTMLElement) {
    this.root = root

    this.nextScreen = this.nextScreen.bind(this)
    this.prevScreen = this.prevScreen.bind(this)
    this.nextSpineItem = this.nextSpineItem.bind(this)
    this.prevSpineItem = this.prevSpineItem.bind(this)

    this.init()
    this.bindEvents()
  }

  public addLocationChangedListener(callback: Function): void {
    this.locationChangedCallbacks.push(callback)
  }

  public setView(v: LayoutView): void {
    this.bookView = v
    this.bookView.attachToHost(this.clipContainer)
    this.bookView.setViewOffsetGetter(() => {
      return this.viewOffset
    })
    this.bookView.setViewportSizeGetter(() => {
      return this.getViewportSize()
    })
    this.containersLayer.addContainer(this.bookView.containerElement(), {
      needToAttach: false,
    })
  }

  public reset(): void {
    this.renderTransitionsForTransitioningContainers('translateX(0px)') // setting containers transition to 0, to avoid page jump on anchor click
    this.startPos = undefined
    this.endPos = undefined
  }

  public getZoomScale(): number {
    return this.zoomScale
  }

  public setZoomScale(scale: number): void {
    const clipperBoundingBox = this.clipContainer.getBoundingClientRect()
    // because we can't achieve very accurate calculations,
    // and each time zooming adds an error because of limited precisions and so on,
    // it is better to reset values for the 'scale' === 1
    const isNoScale = scale === 1

    // clipperBoundingBox.width * scale / this.zoomScale - this.contentContainer.clientwidth
    // ^ this is the difference in size between the NEW SIZE of clipper and content container
    // divide by 2 because we only want offset for one side
    // divide by scale because translate values affected by scale value
    const extraWidth = isNoScale
      ? 0
      : Math.max(
          ((clipperBoundingBox.width * scale) / this.zoomScale -
            this.contentContainer.clientWidth) /
            2 /
            scale,
          0,
        )
    const extraHeight = isNoScale
      ? 0
      : Math.max(
          ((clipperBoundingBox.height * scale) / this.zoomScale -
            clipperBoundingBox.height / this.zoomScale) /
            2 /
            scale,
          0,
        )

    const scaleString: string = isNoScale ? '' : `scale(${scale})`
    const translateXString = extraWidth ? `translateX(${extraWidth}px)` : ''
    const translateYString = extraHeight ? `translateY(${extraHeight}px)` : ''
    const transformString = `${scaleString} ${translateXString} ${translateYString}`

    this.clipContainer.style.transform = transformString.trim()

    if (isNoScale) {
      // this switching allows to solve the issue when overflow = 'auto' adds unwonted scrollbars
      // this allows to recalculate scrollbars
      const overflowTemp = 'hidden'
      const contentContainerStyleOverflow = this.contentContainer.style.overflow

      this.contentContainer.style.overflow = overflowTemp
      // TODO - shouldn't "setZoomScale" be async?
      requestAnimationFrame(() => {
        if (this.contentContainer.style.overflow === overflowTemp) {
          // if hasn't been changed from the 'hidden' to something else, set the previous value
          this.contentContainer.style.overflow = contentContainerStyleOverflow
        }
      })
    }
    this.zoomScale = scale
  }

  public setScrollMode(mode: ScrollMode): void {
    this.root.style.overflowX = 'auto'
    this.root.style.overflowY = 'auto'
    // tslint:disable-next-line:no-any
    ;(this.root.style as any).webkitOverflowScrolling = 'auto'

    // disable scrolling with rtl books for now
    if (
      this.bookView &&
      this.bookView.isRightToLeft() &&
      !this.bookView.isVerticalLayout()
    ) {
      return
    }

    this.scrollMode = mode
    if (
      this.scrollMode === ScrollMode.Publication ||
      this.scrollMode === ScrollMode.SpineItem
    ) {
      if (this.bookView.isVerticalLayout()) {
        this.root.style.overflowY = 'scroll'
      } else {
        this.root.style.overflowX = 'scroll'
      }

      this.clipContainer.style.overflow = 'visible'

      // tslint:disable-next-line:no-any
      ;(this.root.style as any).webkitOverflowScrolling = 'touch'
    }
  }

  public setViewportSize(
    size: number,
    size2nd: number,
    verticalPadding = 0,
  ): void {
    this.viewportSize = size
    this.viewportSize2nd = size2nd
    this.visibleViewportSize = this.viewportSize
    this.verticalPadding = verticalPadding

    // this.root.width and height are intentionally not set here
    // since it will cause wired zoom problem in Safari on iOS
    if (this.bookView) {
      let w
      let h
      if (this.bookView.isVerticalLayout()) {
        w = `${this.viewportSize2nd}px`
        h = `${this.viewportSize}px`
        this.viewportSize = this.viewportSize - verticalPadding
      } else {
        w = `${this.visibleViewportSize}px`
        h = `${this.viewportSize2nd}px`
        this.viewportSize2nd = this.viewportSize2nd - verticalPadding
      }

      this.contentContainer.style.width = w
      this.contentContainer.style.height = h

      this.clipContainer.style.width = w
      this.clipContainer.style.height = h
      this.clipContainer.style.display = 'flex'
      this.clipContainer.style.alignItems = 'center'
    }
  }

  public getViewportSize(): number {
    return this.viewportSize
  }

  public getViewportSize2nd(): number {
    return this.viewportSize2nd
  }

  public getVisibleViewportSize(): number {
    return this.visibleViewportSize
  }

  public setPrefetchPercent(percent: number): void {
    this.prefetchPercent = percent
  }

  public getStartPosition(): PaginationInfo | undefined {
    return this.startPos
  }

  public getEndPosition(): PaginationInfo | undefined {
    return this.endPos
  }

  public translate(delta: number): void {
    this.updateViewOffset(delta)
    this.render()
  }

  public async snapToScreenBoundary(
    refOffset: number,
    dir: SnapDirection = SnapDirection.Auto,
    threshold = 0.5,
    token?: CancellationToken,
    transitionEndCallback?: () => void,
  ): Promise<void> {
    let computedDir = dir
    if (dir === SnapDirection.Auto) {
      if (this.viewOffset > refOffset) {
        const delta = (this.viewOffset - refOffset) / this.visibleViewportSize
        if (delta > threshold) {
          computedDir = SnapDirection.Next
        }
      } else {
        const delta = (refOffset - this.viewOffset) / this.viewportSize
        if (delta > threshold) {
          computedDir = SnapDirection.Prev
        }
      }
    }

    const newPos = [refOffset]
    switch (computedDir) {
      case SnapDirection.Next:
        if (this.canGoNextScreen(refOffset)) {
          newPos[0] = refOffset + this.visibleViewportSize
        }
        break
      case SnapDirection.Prev:
        if (!this.canGoPrevScreen(refOffset, newPos)) {
          newPos[0] = refOffset
        }
        break
      case SnapDirection.Auto:
        break
    }

    await this.renderAtOffset(newPos[0], token, transitionEndCallback)
  }

  public async renderAtOffset(
    pos: number,
    token?: CancellationToken,
    transitionEndCallback?: () => void,
  ): Promise<void> {
    this.scrollFromInternal = true

    // this.viewOffset = pos;
    // this.render();

    this.viewOffset = await this.ensureViewportFilledAtPosition(pos, token)
    this.adjustScrollPosition()
    this.updatePositions()

    this.scrollFromInternal = false

    // This call is important since the viewoffset and
    // scroller position may out of sync if additonal
    // spine item is loaded
    let resolveOnTransitionEnd = (): void => undefined
    // eslint-disable-next-line prefer-const
    let timer: ReturnType<typeof setTimeout> | undefined
    function transitionEndCallbackInternal(): void {
      timer && clearTimeout(timer)
      resolveOnTransitionEnd()
      transitionEndCallback?.()
    }
    this.render(transitionEndCallbackInternal)

    timer = setTimeout(() => {
      transitionEndCallbackInternal()
    }, MAX_TIMEOUT_FOR_VIEWPORT_TRANSITION_END_MS)
    await new Promise<void>((res) => {
      resolveOnTransitionEnd = res
    })

    if (token && token.isCancelled) {
      return
    }

    await this.onPagesReady(token)
    if (token && token.isCancelled) {
      return
    }

    this.onLocationChanged()

    await this.updatePrefetch(token)
  }

  public async renderAtSpineItem(
    spineItemIndex: number,
    token?: CancellationToken,
  ): Promise<void> {
    await this.ensureContentLoadedAtSpineItemRange(
      spineItemIndex,
      spineItemIndex,
      token,
    )
    if (token && token.isCancelled) {
      return
    }
    const pos = this.bookView.getSpineItemViewOffset(spineItemIndex)
    if (pos === undefined) {
      return
    }

    this.viewOffset = await this.ensureViewportFilledAtPosition(
      pos,
      token,
      true,
    )

    this.adjustScrollPosition()
    this.render()

    if (token && token.isCancelled) {
      return
    }

    await this.onPagesReady(token)
    if (token && token.isCancelled) {
      return
    }

    this.onLocationChanged()

    await this.updatePrefetch(token)
  }

  public async renderAtLocation(
    loc: Location,
    token?: CancellationToken,
  ): Promise<void> {
    const spineItemIndex = this.bookView.findSpineItemIndexByHref(loc.getHref())

    if (spineItemIndex < 0) {
      return
    }

    await this.ensureContentLoadedAtSpineItemRange(
      spineItemIndex,
      spineItemIndex,
      token,
    )
    if (token && token.isCancelled) {
      return
    }

    const offset = await this.bookView.getOffsetFromLocation(loc)
    if (offset === undefined) {
      return
    }
    this.viewOffset = await this.ensureViewportFilledAtPosition(
      offset,
      token,
      true,
    )
    this.adjustScrollPosition()
    await new Promise<void>((res) => this.render(res))

    if (token && token.isCancelled) {
      return
    }

    await this.onPagesReady(token)
    if (token && token.isCancelled) {
      return
    }

    this.onLocationChanged()

    await this.updatePrefetch(token)
  }

  public async renderAtAnchorLocation(
    href: string,
    eleId?: string,
    token?: CancellationToken,
  ): Promise<void> {
    const spineItemIndex = this.bookView.findSpineItemIndexByHref(href)

    if (spineItemIndex < 0) {
      return
    }

    await this.ensureContentLoadedAtSpineItemRange(
      spineItemIndex,
      spineItemIndex,
      token,
    )
    if (token && token.isCancelled) {
      return
    }

    const offset = await this.bookView.getOffsetFromAnchor(href, eleId)

    if (offset === undefined) {
      return
    }

    this.viewOffset = await this.ensureViewportFilledAtPosition(
      offset,
      undefined,
      true,
    )

    this.adjustScrollPosition()
    this.render()

    if (token && token.isCancelled) {
      return
    }

    await this.onPagesReady(token)
    if (token && token.isCancelled) {
      return
    }

    this.onLocationChanged()

    await this.updatePrefetch(token)
  }

  public async nextScreen(token?: CancellationToken): Promise<void> {
    if (this.canGoNextScreen(this.viewOffset)) {
      await this.waitForRenderAtOffset(
        this.viewOffset + this.visibleViewportSize,
        token,
      )
    }
  }

  public async prevScreen(token?: CancellationToken): Promise<void> {
    const newPos = [0]
    if (this.canGoPrevScreen(this.viewOffset, newPos)) {
      await this.waitForRenderAtOffset(newPos[0], token)
    }
  }

  protected async waitForRenderAtOffset(
    offset: number,
    token?: CancellationToken,
  ) {
    let transitionEndCallback: () => void = () => undefined
    const waitingForTransitionEnd = new Promise<void>((res) => {
      transitionEndCallback = res
    })
    const waitingForRender = this.renderAtOffset(
      offset,
      token,
      transitionEndCallback,
    )
    await Promise.all([waitingForTransitionEnd, waitingForRender])
  }

  public async nextSpineItem(token?: CancellationToken): Promise<void> {
    if (this.startPos === undefined) {
      return
    }

    await this.renderAtSpineItem(this.startPos.spineItemIndex + 1, token)
  }

  public async prevSpineItem(token?: CancellationToken): Promise<void> {
    if (this.startPos === undefined) {
      return
    }

    await this.renderAtSpineItem(this.startPos.spineItemIndex - 1, token)
  }

  public async ensureLoaded(token?: CancellationToken): Promise<void> {
    await this.bookView.ensureLoaded(token)
    this.updatePositions()
  }

  public visibleSpineItemIndexRange(): number[] {
    const indices: number[] = []
    const startPageInfo = this.bookView.getPaginationInfoAtOffset(
      this.viewOffset,
    )
    if (startPageInfo.length === 0) {
      return indices
    }

    const pos = this.getEndOffset()
    const endPageInfo = this.bookView.getPaginationInfoAtOffset(pos)
    if (endPageInfo.length === 0) {
      return indices
    }

    indices.push(startPageInfo[startPageInfo.length - 1].spineItemIndex)
    indices.push(endPageInfo[0].spineItemIndex)

    return indices
  }

  public getBookViewElement(): HTMLElement {
    return this.bookView.containerElement()
  }

  public getClipContainerWidth(): number {
    return this.clipContainer.clientWidth
  }

  public getSpineItemView(spineItemIndex: number): SpineItemView | undefined {
    return this.bookView.getSpineItemView(spineItemIndex)
  }

  public getSpineItemViewByHref(href: string): SpineItemView | undefined {
    const spineItemIndex = this.bookView.findSpineItemIndexByHref(href)
    return this.getSpineItemView(spineItemIndex)
  }

  public getOffsetInSpineItemView(siIndex: number): number | undefined {
    return this.bookView.getOffsetInSpineItemView(siIndex, this.viewOffset)
  }

  public getSpineItemIndexByHref(href: string): number {
    return this.bookView.findSpineItemIndexByHref(href)
  }

  public onVisiblePagesReady(callback: (cv: IContentView) => void): void {
    this.visiblePagesReadyCallbacks.push(callback)
  }

  public onVisiblePagesLoading(callback: () => void) {
    this.visiblePagesLoadingCallbacks.push(callback)
  }

  public getViewScale(siIndex: number): number {
    const view = this.bookView.getSpineItemView(siIndex)
    if (!view) {
      return 1
    }

    return view.getScale()
  }

  public beginViewUpdate(): void {
    this.bookView.beginViewUpdate()
  }

  public endViewUpdate(): void {
    this.bookView.endViewUpdate()
  }

  public onPageSizeChanged(
    pageWidth: number,
    numOfPages: number,
    colGap: number,
  ): void {
    if (numOfPages <= 0) {
      this.contentContainer.style.width = this.root.style.width
      return
    }
    const containerWidth = Math.min(
      pageWidth * numOfPages + colGap,
      this.viewportSize,
    )
    const visibleWidth = Math.min(pageWidth * numOfPages, this.viewportSize)
    this.contentContainer.style.width = `${containerWidth}px`

    const paddingAdjust = (containerWidth - visibleWidth) / 2
    const styleUpdated: CSSRules = {
      width: `${containerWidth - paddingAdjust * 2}px`,
      paddingLeft: `${paddingAdjust}px`,
      paddingRight: `${paddingAdjust}px`,
    }

    this.updateClippersStyle(styleUpdated)
    this.visibleViewportSize = visibleWidth
    this.bookMargins = paddingAdjust
    this.updateLayoutParametersForPageLabelsView()
  }

  public setAndApplyAnimationProperties(
    animationProperties: Partial<CSSStyleDeclaration>,
  ): void {
    this.containersLayer.updateAnimationProps(
      animationProperties as Partial<AnimationProperties>,
    )
  }

  // Width of visible pages and any padding/border/margin "attached" to those pages
  public getContainerWidth(): number {
    if (this.bookView.isFixedLayout) {
      const visibleSpineItemIndex = this.visibleSpineItemIndexRange()
      const width = this.bookView.getSpreadWidthOfSpineItem(
        visibleSpineItemIndex[0],
      )
      return width || 0
    } else {
      return this.contentContainer.offsetWidth
    }
  }

  public getContentViewVerticalOffset(): number {
    const pageInfo = this.bookView.getPaginationInfoAtOffset(this.viewOffset)
    if (pageInfo[0]) {
      return pageInfo[0].view.getContentViewVerticalOffset()
    }

    return 0
  }

  public handlePageLabelsManager(
    pageLabelManager: PageLabelManagerEventEmitter,
  ): void {
    // TODO - perhaps we need to unset these listeners in future
    pageLabelManager.addListenerPageLabelsPositionsUpdate(this.renderPageLabels)
    pageLabelManager.addPageLabelsVisibleRangeUpdatedListener(
      this.handleVisibleRangeUpdate,
    )
    pageLabelManager.addPageLabelsVisibilityFlagListener(
      this.handlePageLabelsVisibilityChange,
    )
  }

  public setUnloadSpineItemHandler(
    handleUnloadSpineItemCallback: HandleUnloadSpineItemCallback,
  ): void {
    if (typeof handleUnloadSpineItemCallback !== 'function') {
      throw new Error('The argument should be a function')
    }
    this.bookView.setUnloadSpineItemHandler(handleUnloadSpineItemCallback)
  }

  private onLocationChanged(): void {
    this.locationChangedCallbacks.forEach((eventCb) => eventCb())
  }

  private init(): void {
    this.contentContainer = document.createElement('div')
    this.contentContainer.id = 'viewport-content'
    this.contentContainer.style.margin = 'auto'
    this.contentContainer.style.position = 'relative'
    this.contentContainer.style.overflow = 'auto'
    this.root.appendChild(this.contentContainer)

    this.clipContainer = document.createElement('div')
    this.clipContainer.id = ViewportClipperElementId
    this.clipContainer.style.overflowX = 'hidden'
    this.clipContainer.style.overflowY = 'hidden'
    this.clipContainer.style.position = 'relative'
    this.clipContainer.style.margin = ''
    this.clipContainer.style.left = ''
    this.clipContainer.style.right = ''
    // this is required by Safari on iOS to maintain
    // corret clipping while css transform is applied
    this.clipContainer.style.clipPath = 'content-box'
    this.contentContainer.appendChild(this.clipContainer)
    this.initContainersLayerInstance()
  }

  public initReflowablePageLabelsView(
    pageLabelVisibilityHandler: PageLabelVisibilityHandler<
      PageLabelVisibilityHandlerTypeName.Reflowable
    >,
  ): void {
    const pageLabelsView = new PageLabelsView({
      pageLabelVisibilityHandler,
      getSpineItemViewOffset: (spineItemIndex: number): number | undefined =>
        this.bookView.getSpineItemViewOffset(spineItemIndex),
    })

    pageLabelsView.attachToContainersLayer(this.containersLayer)
    this.pageLabelsView = pageLabelsView
  }

  /**
   * Return a root Document element matching the spineItemHref
   * or null if there is no such spine on the screen.
   *
   * @param {string} spineItemHref
   * @returns {(Document | null)}
   * @memberof Viewport
   */
  public getSpineItemDocumentByHrefOrNull(
    spineItemHref: string,
  ): Document | null {
    const iframe = this.getSpineItemViewByHref(spineItemHref)
      ?.getContentView()
      ?.element()
      ?.getElementsByTagName('iframe')[0]
    if (!iframe) {
      return null
    }

    const iframeDocument = iframe.contentDocument
    if (!iframeDocument) {
      return null
    }

    return iframeDocument
  }

  public getDocumentsOfVisibleSpineItems(): Document[] {
    const visibleSpineItemDocuments: Document[] = []
    const indexArray = this.visibleSpineItemIndexRange()
    for (let i = 0; i < indexArray.length; i++) {
      const spineItemIndex = indexArray[i]
      const spineItemIframeElement = this.getSpineItemView(spineItemIndex)
        ?.getContentView()
        .element()
        .getElementsByTagName('iframe')[0]

      const iframeContentDocumentOrUndefined =
        spineItemIframeElement?.contentDocument
      if (
        iframeContentDocumentOrUndefined &&
        !visibleSpineItemDocuments.includes(iframeContentDocumentOrUndefined)
      ) {
        visibleSpineItemDocuments.push(iframeContentDocumentOrUndefined)
      }
    }
    return visibleSpineItemDocuments
  }

  private updateViewOffset(delta: number) {
    this.viewOffset += delta
  }
  private getPrefetchSize(): number {
    return Math.ceil(this.viewportSize * this.prefetchPercent)
  }

  private bindEvents(): void {
    this.root.addEventListener('scroll', async (_ev: Event) => {
      if (this.scrollMode === ScrollMode.None || this.scrollFromInternal) {
        return
      }

      this.viewOffset = this.scrollOffset()
      // console.log(`offset: ${this.viewOffset}`);

      if (this.scrollMode === ScrollMode.Publication) {
        const prefetchSize = this.getPrefetchSize()
        const start = this.viewOffset - prefetchSize
        const end = this.viewOffset + this.viewportSize + prefetchSize
        if (
          (end >= this.bookView.getLoadedEndPosition() &&
            this.bookView.hasMoreAfterEnd()) ||
          (start <= this.bookView.getLoadedStartPostion() &&
            this.bookView.hasMoreBeforeStart())
        ) {
          await this.ensureConentLoadedAtRange(start, end)
          this.adjustScrollPosition()
          await this.onPagesReady(this.scrollRequestToken)
        }
      }
      this.render()
    })
  }

  private canGoNextScreen(refOffset: number): boolean {
    const newPos = refOffset + this.visibleViewportSize
    const loadedEndPos = this.bookView.getLoadedEndPosition()
    if (newPos >= loadedEndPos && !this.bookView.hasMoreAfterEnd()) {
      return false
    }

    return (
      newPos !== this.viewOffset &&
      (newPos <= loadedEndPos || this.bookView.hasMoreAfterEnd())
    )
  }

  private canGoPrevScreen(refOffset: number, newPrevPos: number[]): boolean {
    let newPos = refOffset - this.visibleViewportSize
    const loadedStartPos = this.bookView.getLoadedStartPostion()
    // Ensure not to go beyond begining of the book
    if (newPos < loadedStartPos && !this.bookView.hasMoreBeforeStart()) {
      newPos = loadedStartPos
    }

    newPrevPos[0] = newPos

    return (
      newPos !== this.viewOffset &&
      (newPos >= loadedStartPos || this.bookView.hasMoreBeforeStart())
    )
  }

  private async ensureConentLoadedAtRange(
    start: number,
    end: number,
  ): Promise<void> {
    if (this.scrollRequestToken) {
      this.scrollRequestToken.isCancelled = true
    }
    this.scrollRequestToken = new CancellationToken()
    const t = this.scrollRequestToken
    await this.bookView.ensureConentLoadedAtRange(start, end, t)
    if (this.scrollRequestToken === t) {
      this.scrollRequestToken = undefined
    }
    if (!t.isCancelled) {
      await this.bookView.removeOutOfRangeSpineItems(start, end)
    }
  }

  private async updatePrefetch(token?: CancellationToken): Promise<void> {
    const prefetchSize = this.getPrefetchSize()
    const start = this.viewOffset - prefetchSize
    const end = this.viewOffset + this.getScaledViewportSize() + prefetchSize
    this.bookView.removeOutOfRangeSpineItems(start, end)

    await this.bookView.ensureConentLoadedAtRange(start, end, token)
    this.updatePositions()

    if (this.scrollMode === ScrollMode.SpineItem) {
      this.showOnlyCurrentSpineItemRange()
    }
  }

  private updatePositions(): void {
    const startInfo = this.bookView.getPaginationInfoAtOffset(this.viewOffset)
    if (startInfo.length > 0) {
      this.startPos = startInfo[startInfo.length - 1]
    } else {
      this.startPos = undefined
    }

    const endPos = this.getEndOffset()
    const endInfo = this.bookView.getPaginationInfoAtOffset(endPos)
    if (endInfo.length > 0) {
      this.endPos = endInfo[0]
    } else {
      this.endPos = undefined
    }
  }

  private adjustScrollPosition(): void {
    if (this.scrollMode !== ScrollMode.Publication) {
      return
    }

    this.scrollFromInternal = true
    const adjustment = this.bookView.adjustLoadedConentRangeToPositive()
    this.scrollFromInternal = false
    if (adjustment === 0) {
      return
    }

    this.updateViewOffset(-adjustment)
  }

  private render(transitionEndCallback?: () => void): void {
    let transformString = ''
    let isUpdateScrollFromViewOffset = false
    if (this.scrollMode === ScrollMode.None) {
      if (this.bookView.isVerticalLayout()) {
        transformString = `translateY(${-this.viewOffset}px)`
      } else {
        if (this.bookView.isRightToLeft()) {
          const offset = this.getEndOffset()
          transformString = `translateX(${offset}px)`
        } else {
          transformString = `translateX(${-this.viewOffset}px)`
        }
      }
    } else {
      transformString = 'translateX(0)'
      isUpdateScrollFromViewOffset = true
    }

    this.renderTransitionsForTransitioningContainers(transformString)
    if (isUpdateScrollFromViewOffset) {
      this.updateScrollFromViewOffset()
    }
    if (transitionEndCallback) {
      this.containersLayer.addTransitionEndOnceCallback(transitionEndCallback)
    }
    this.updatePositions()
    this.renderPageLabels([])
  }

  private renderTransitionsForTransitioningContainers(
    transformString: string,
  ): void {
    this.containersLayer.applyCssPropsToContainers({
      transform: transformString,
    })
  }

  private scrollOffset(): number {
    return this.bookView.isVerticalLayout()
      ? this.root.scrollTop
      : this.root.scrollLeft
  }

  private updateScrollFromViewOffset(): void {
    if (this.bookView.isVerticalLayout()) {
      this.root.scrollTop = this.viewOffset
    } else {
      this.root.scrollLeft = this.viewOffset
    }
  }

  /*
    `shouldPrefetch` flag is added to disable prefetch in certain cases
  (e.g. renderAtOffset()) since it may cause UI stuttering.
    Theoretically prefetch is unnecessary here because updatePrefetch()
  is called in the renderAt*() functions. But clipToVisibleRange()
  requires prev page loaded to calculate the page layout in double page
  spread mode for fixed layout books. renderAtOffset() could have prefetch
  disabled here because it is called in page by page flipping, and prev
  page is loaded when this function is being called.
    A better fix could be to check if prev page is required dynamically.
  If so, load the prev page. However it seems like calling
  ensureConentLoadedAtRange() in a row will cause stability issues in
  unit tests. That should be looked into before improving the fix
  */
  private async ensureViewportFilledAtPosition(
    pos: number,
    token?: CancellationToken,
    shouldPrefetch = false,
  ): Promise<number> {
    for (const callback of this.visiblePagesLoadingCallbacks) {
      callback()
    }

    const prefetchSize = this.getPrefetchSize()

    const start = pos - (shouldPrefetch ? prefetchSize : 0)
    const end =
      pos + this.getScaledViewportSize() + (shouldPrefetch ? prefetchSize : 0)
    await this.bookView.ensureConentLoadedAtRange(start, end, token)
    if (token && token.isCancelled) {
      return pos
    }

    let newPos = pos
    if (this.scrollMode === ScrollMode.None) {
      newPos = this.adjustVisibleRange(pos)
      this.setZoomScale(this.zoomScale)
    }

    this.updatePositions()

    if (this.scrollMode === ScrollMode.SpineItem) {
      this.showOnlyCurrentSpineItemRange()
    }

    return newPos
  }

  private async ensureContentLoadedAtSpineItemRange(
    startIndex: number,
    endIndex: number,
    token?: CancellationToken,
  ): Promise<void> {
    this.reset()

    for (const callback of this.visiblePagesLoadingCallbacks) {
      callback()
    }

    await this.bookView.ensureContentLoadedAtSpineItemRange(
      startIndex,
      endIndex,
      token,
    )
    if (token && token.isCancelled) {
      return
    }

    if (this.scrollMode === ScrollMode.SpineItem) {
      this.bookView.showOnlySpineItemRange(startIndex)
      this.viewOffset = 0
    }
  }

  private adjustVisibleRange(start: number): number {
    let numOfPagePerSpread = this.bookView.numberOfPagesPerSpread()
    if (
      (numOfPagePerSpread >= 0 && numOfPagePerSpread <= 1) ||
      !this.bookView.isFixedLayout
    ) {
      return start
    }

    let pagesBefore = 0
    numOfPagePerSpread = 1
    const isOnRight = this.bookView.isOnRightOfdoublePageSpread(
      Math.ceil(start),
    )

    //We should only need to adjust when the current page
    // is one the right in double page spread
    if (isOnRight) {
      pagesBefore = 1
      numOfPagePerSpread = 2
    }

    if (pagesBefore === 0) {
      return start
    }

    const pageRanges = this.bookView.fixedLayoutPageSizes(
      Math.ceil(start),
      0,
      pagesBefore,
    )
    pageRanges.sort((page1: [number, number], page2: [number, number]) => {
      const page1Dist = Math.min(
        Math.abs(this.viewOffset - page1[0]),
        Math.abs(this.viewOffset - page1[1]),
      )
      const page2Dist = Math.min(
        Math.abs(this.viewOffset - page2[0]),
        Math.abs(this.viewOffset - page2[1]),
      )

      return page1Dist - page2Dist
    })

    const spreadPages = pageRanges.slice(0, numOfPagePerSpread)

    let firstPage = spreadPages[0]
    let lastPage = spreadPages[spreadPages.length - 1]
    if (lastPage[0] < firstPage[0]) {
      // eslint-disable-next-line no-extra-semi
      ;[firstPage, lastPage] = [lastPage, firstPage]
    }

    return firstPage[0]
  }

  private showOnlyCurrentSpineItemRange(): void {
    if (!this.startPos) {
      return
    }

    this.bookView.showOnlySpineItemRange(this.startPos.spineItemIndex)
  }

  private getScaledViewportSize(): number {
    return this.viewportSize * this.bookView.getZoomScale()
  }

  private getEndOffset(): number {
    let offset = this.viewOffset + this.visibleViewportSize
    if (offset > this.bookView.getLoadedEndPosition()) {
      offset = this.bookView.getLoadedEndPosition()
    }
    return offset
  }

  private async onPagesReady(token?: CancellationToken): Promise<void> {
    // Make sure all spine items are loaded so all CONTENT_DOCUMENT_LOADED
    // have been emitted
    await this.bookView.ensureLoaded(token)
    if (token && token.isCancelled) {
      return
    }

    const pageInfo = this.bookView.getPaginationInfoAtOffset(this.viewOffset)
    if (pageInfo.length === 0) {
      return
    }

    const contentView = pageInfo[pageInfo.length - 1].view.getContentView()
    for (const callback of this.visiblePagesReadyCallbacks) {
      callback(contentView)
    }
  }

  private updateClippersStyle(style: CSSRules): void {
    applyToStyleDeclaration(this.clipContainer.style, style)
    this.containersLayer.applyCssPropsToClipper(style)
  }

  private initContainersLayerInstance(): void {
    const containersLayer = new ContainersLayer()

    this.containersLayer = containersLayer
    containersLayer.attachToHost(this.contentContainer)
  }

  private getPageLabelRendererPageLayoutParameters(): PageLabelRendererPageLayoutParameters {
    const bookView = this.bookView

    if (!bookView) {
      throw new Error('A book layout instance has not been initialized yet')
    }

    const containerOffsetTop: number = getContainerOffsetTopByRect(
      this.contentContainer.getBoundingClientRect(),
    )
    const containerOffsetLeft: number = getContainerOffsetLeftByRect(
      this.contentContainer.getBoundingClientRect(),
    )
    const pageLabelsIFrameContainerOffsets: PageLabelContentContainerOffsets = {
      top: containerOffsetTop + this.verticalPadding / 2,
      left: containerOffsetLeft,
    }

    const columnGap: number = bookView.getColumnGap()
    const onePageWidth: number = bookView.getPageWidth()
    const numberOfPagesPerSpread: number = bookView.numberOfPagesPerSpread()
    const clipContainerWidth: number = this.getClipContainerWidth()
    const viewStartOffset: number = this.viewOffset
    const viewEndOffset: number = this.getEndOffset()
    return {
      onePageWidth,
      numberOfPagesPerSpread,
      clipContainerWidth,
      viewOffsets: {
        startOffset: viewStartOffset,
        endOffset: viewEndOffset,
      },
      pageLabelsIFrameContainerOffsets,
      bookMargins: this.bookMargins,
      columnGap,
    }
  }

  private updateLayoutParametersForPageLabelsView(): void {
    this.pageLabelsView?.updateLayoutParameters(
      this.getPageLabelRendererPageLayoutParameters(),
    )
  }

  private renderPageLabels = (
    pageLabelsInfo: PageLabelInfoWithPosition[],
  ): void => {
    this.pageLabelsView?.renderPageLabels(
      pageLabelsInfo,
      this.getPageLabelRendererPageLayoutParameters(),
    )
  }

  private handleVisibleRangeUpdate = (
    visibleRangeUpdate: VisibleRangeUpdate,
  ): void => {
    this.pageLabelsView.handleVisibleRangeUpdate(visibleRangeUpdate)
  }

  private handlePageLabelsVisibilityChange = (
    arePageLabelsVisible: boolean,
  ): void => {
    this.pageLabelsView.handlePageLabelsVisibilityChange(arePageLabelsVisible)
  }
}
