import {
  IFrameContentInjector,
  IFrameContentInjectorParameters,
} from '../iframe-loader'

import type {
  ContentInjectionScriptFactory,
  SendReplaceURLContentMessageToSW,
  SpineItemIFrameSrcAttributeFactoryFactory,
} from './types'

export const IFrameLoaderReplaceContentMessageType = 'iframe_replace_content'

export interface CreateInjectSpineHTMLCodeUsingIframeScriptImplParameters {
  /**
   * Send a message to SW to replace the content for a URL
   *
   * @type {SendReplaceURLContentMessageToSW}
   * @memberof CreateInjectSpineHTMLCodeUsingIframeScriptImplParameters
   */
  sendMessageToInjectScriptIntoIFrame: SendReplaceURLContentMessageToSW
  /**
   * Create a script for IFrame that will replace its content
   *
   * @type {ContentInjectionScriptFactory}
   * @memberof CreateInjectSpineHTMLCodeUsingIframeScriptImplParameters
   */
  iframeScriptFactory: ContentInjectionScriptFactory
  /**
   * A function that is used to create the 'src' attribute value
   * of an iframe element.
   *
   * @type {SpineItemIFrameSrcAttributeFactoryFactory}
   * @memberof CreateInjectSpineHTMLCodeUsingIframeScriptImplParameters
   */
  spineItemIFrameSrcValueFactory: SpineItemIFrameSrcAttributeFactoryFactory
}

export function createInjectSpineHTMLCodeUsingIframeScriptImpl(
  parameters: CreateInjectSpineHTMLCodeUsingIframeScriptImplParameters,
): IFrameContentInjector {
  const {
    iframeScriptFactory,
    sendMessageToInjectScriptIntoIFrame,
    spineItemIFrameSrcValueFactory,
  } = parameters

  if (!iframeScriptFactory) {
    throw new Error('"iframeScriptFactory" is empty')
  }
  if (!sendMessageToInjectScriptIntoIFrame) {
    throw new Error('"sendMessageToInjectScriptIntoIFrame" is empty')
  }
  if (!spineItemIFrameSrcValueFactory) {
    throw new Error('"spineItemIFrameSrcValueFactory" is not defined')
  }

  const injectSpineHTMLCodeUsingIframeScriptImpl: IFrameContentInjector = async function injectSpineHTMLCodeUsingIframeScript(
    parameters: IFrameContentInjectorParameters,
  ): Promise<void> {
    const {
      documentContent,
      documentMIMEType,
      documentUrl,
      iframe,
    } = parameters

    if (!documentContent) {
      throw new Error('The HTML code is empty')
    }
    if (!documentMIMEType) {
      throw new Error('The document MIME type is empty')
    }
    if (!documentUrl) {
      throw new Error('The document url address type is empty')
    }
    if (!iframe) {
      throw new Error('The "iframe" parameter is empty')
    }

    // this is a fake url, which is not exists
    const urlFinal = await spineItemIFrameSrcValueFactory(documentUrl)
    const iframeScript: string = iframeScriptFactory(
      IFrameLoaderReplaceContentMessageType,
    )
    await sendMessageToInjectScriptIntoIFrame({
      urlAffected: urlFinal,
      targetContent: iframeScript,
      contentMimeTypeWithEncoding: `text/html; charset=UTF-8`,
    })

    iframe.src = urlFinal

    // wait when iframe will load the script and be ready to receive the message
    await new Promise<unknown>((res) =>
      iframe.addEventListener('load', res, { once: true }),
    )

    const iframeWindow = iframe.contentWindow
    if (!iframeWindow) {
      throw new Error(
        'Could not find iframe content window - unable to add load / unload listeners',
      )
    }
    // send a message with a HTML text to replace the content of the iframe
    iframeWindow.postMessage(
      {
        type: IFrameLoaderReplaceContentMessageType,
        documentUrl: urlFinal,
        documentMIMEType,
        documentContent,
      },
      '*',
    )
  }
  return injectSpineHTMLCodeUsingIframeScriptImpl
}
