import { checkIfHtmlElement } from './check-if-html-element'

/**
 * Loads binary data to the image element.
 *
 * @export
 * @param {HTMLImageElement} imgElement - an image HTML element where to load the binary source
 * @param {(string | Blob | MediaSource)} imageContent - the binary data or image url
 * @return {Promise<void>}
 */
export async function loadBlobToImage(
  imgElement: HTMLImageElement,
  imageContent: string | Blob | MediaSource,
): Promise<void> {
  if (!checkIfHtmlElement(imgElement)) {
    throw new Error('The image should be an HTMLElement')
  }
  if (!imageContent) {
    throw new Error('The image content should be defined')
  }

  const imageLoadedPendingPromise = new Promise<unknown>((res) => {
    imgElement.onload = res
  })
  const imageUrl: string =
    typeof imageContent === 'string'
      ? imageContent
      : URL.createObjectURL(imageContent)
  imgElement.src = imageUrl
  await imgElement.decode()
  await Promise.race([
    imageLoadedPendingPromise,
    new Promise((_res, rej) => {
      setTimeout(() => rej(new Error('Timeout')), 100)
    }),
  ])
}
