import { CSSStylesPartialDefaults } from '../navigator/const'

import type { CSSStyles } from './types'

/**
 * Returns a full set of CSS rules applied to the element.
 * Safari does not combine
 *
 * @export
 * @param {HTMLElement} element
 * @return {CSSStyles}
 */
export function getElementCSSStyles(element: HTMLElement): CSSStyles {
  const windowOwner = element.ownerDocument.defaultView

  if (!windowOwner) {
    throw new Error('The element is not attached to any document')
  }
  const elementStyles = windowOwner.getComputedStyle(element)
  // safari doesn't combine these objects properly
  // you should inspect computed styles on it's own as well
  return {
    ...CSSStylesPartialDefaults,
    ...elementStyles,
  }
}

/**
 * Returns a full set of CSS rules applied to the element.
 *
 * @export
 * @param {HTMLElement} element
 * @return {CSSStyles}
 */
export function getComputedStyle(element: HTMLElement): CSSStyleDeclaration {
  return getWindowOwner(element).getComputedStyle(element)
}

function getWindowOwner(element: HTMLElement): Window {
  const windowOwner = element.ownerDocument.defaultView

  if (!windowOwner) {
    throw new Error('The element is not attached to any document')
  }

  return windowOwner
}
