import type { FlowpubCSSAssetUrls, ReadiumCSSAssetUrls } from '../navigator'

/**
 * Derives the full url to Readium CSS files
 * from the url to the root storage that contains
 * all of them.
 *
 * @export
 * @param {string} readiumCssBasePath - path to the root directory/server.
 * @return  {ReadiumCSSAssetUrls}
 */
export function getReadiumCSSAssetUrls(
  readiumCssBasePath: string,
): ReadiumCSSAssetUrls {
  const beforeCssUrl = `${readiumCssBasePath}/ReadiumCSS-before.css`
  const defaultCssUrl = `${readiumCssBasePath}/ReadiumCSS-default.css`
  const afterCssUrl = `${readiumCssBasePath}/ReadiumCSS-after.css`
  return {
    beforeCssUrl,
    defaultCssUrl,
    afterCssUrl,
  }
}

/**
 * Derives the full url to Flowpub CSS files
 * from the url to the root storage that contains
 * all of them.
 *
 * @export
 * @param {string} basePath - path to the root directory/server.
 * @return  {FlowpubCSSAssetUrls}
 */
export function getFlowpubCSSAssetUrls(basePath: string): FlowpubCSSAssetUrls {
  const fixedLayoutCssUrl = `${basePath}/fixed-layout-overrides.css`
  return {
    fixedLayoutCssUrl,
  }
}
