import {
  IFrameDocumentPostProcessor,
  IFrameDocumentPostProcessorParameters,
} from '../iframe-loader'

/**
 * Returns an instance of IFrameDocumentPostProcessor that will sequentially invoke
 * the provided IFrameDocumentPostProcessor functions
 *
 * @export
 * @param {Array<IFrameDocumentPostProcessor>} postprocessors - postprocessors to execute
 * @return {IFrameDocumentPostProcessor}
 */
export function createPostProcessorPipeline(
    postprocessors: Array<IFrameDocumentPostProcessor>,
): IFrameDocumentPostProcessor {
  return async function execPostProcessorPipeline(
    parameters: IFrameDocumentPostProcessorParameters,
  ): Promise<void> {
    for (const postprocessor of postprocessors) {
        await postprocessor(parameters);
    }
  };
}

/**
 * Returns an instance of IFrameDocumentPostProcessor that will invoke
 * the provided IFrameDocumentPostProcessor functions in parallel
 *
 * @export
 * @param {Array<IFrameDocumentPostProcessor>} postprocessors - postprocessors to execute
 * @return {IFrameDocumentPostProcessor}
 */
export function createAsyncPostProcessorPipeline(
    postprocessors: Array<IFrameDocumentPostProcessor>,
): IFrameDocumentPostProcessor {
  return async function execPostProcessorsAsync(
    parameters: IFrameDocumentPostProcessorParameters,
  ): Promise<void> {
    await Promise.all(postprocessors.map(
        (postprocessor) => postprocessor(parameters)
    ));
  };
}
