// TODO - If this is purely processing internal base64 this is fine, but we should be aware that base64 has other considerations like newlines every 72(?) characters and url-safe encodings

function isBase64(str: string): boolean {
  if (str === '' || str.trim() === '') {
    return false
  }
  try {
    return btoa(atob(str)) == str
  } catch (err) {
    return false
  }
}

export function base64ToArrayBuffer(base64: string): ArrayBufferLike {
  try {
    if (!isBase64(base64)) {
      throw new Error(`given input base64 -> ${base64}  is not base64 string`)
    }

    const binaryString = atob(base64)
    const { length } = binaryString
    const bytes = new Uint8Array(length)
    for (let i = 0; i < length; i++) {
      bytes[i] = binaryString.charCodeAt(i)
    }
    return bytes.buffer
  } catch (err) {
    console.error('drm-module:base64ToArrayBuffer exception. ', err)
    throw err
  }
}
