import { base64ToArrayBuffer } from '../utils'
import {
  IFrameDocumentPostProcessor,
  IFrameDocumentPostProcessorParameters,
} from '../../iframe-loader'

import { DatasetPropertyImageBase64Content } from './const'
import { ImagesIFramePostProcessorFactoryParameters } from './types'

/**
 * Returns an instance of IFrameDocumentPostProcessor that will use
 * given parameters.
 * The resulted functions will handle all the images and uses the data from
 * "image.dataset[DatasetPropertyImageBase64Content]" to display them using
 * the function "loadImageData" passed in the parameters.
 *
 * @export
 * @param {ImagesIFramePostProcessorFactoryParameters} parameters - factory parameters.
 * @return {IFrameDocumentPostProcessor}
 */
export function createImagesIFramePostProcessor(
  parameters: ImagesIFramePostProcessorFactoryParameters,
): IFrameDocumentPostProcessor {
  const { loadImageData } = parameters

  if (typeof loadImageData !== 'function') {
    throw new Error('"loadImageData" parameter should be a function')
  }

  async function processImages(
    parameters: IFrameDocumentPostProcessorParameters,
  ): Promise<void> {
    const { document } = parameters

    if (!document) {
      throw new Error('The document should not be empty')
    }
    if (typeof document !== 'object') {
      throw new Error('The document should be an object')
    }

    const images = document.images

    if (!images) {
      throw new Error('The collection of the document images should be defined')
    }

    const pendingPromises: Promise<void>[] = []
    for (let i = 0; i < images.length; i++) {
      const image = images[i]
      const base64ImageData: string | undefined =
        image.dataset[DatasetPropertyImageBase64Content]

      if (!base64ImageData) {
        continue
      }
      delete image.dataset[DatasetPropertyImageBase64Content]
      try {
        const imageBlob: ArrayBuffer = base64ToArrayBuffer(base64ImageData)
        const promisePending = loadImageData(image, imageBlob).catch((err) => {
          console.error(new Error(`Failed to load an image from its source`))
          console.error(err)
        })
        pendingPromises.push(promisePending)
      } catch (err) {
        console.error(err)
      }
    }
    await Promise.all(pendingPromises)
  }
  return processImages
}
