import {
  IFrameDocumentPostProcessorParameters,
} from '../iframe-loader'

export const ParagraphFirstChildImageClassname = 'p-first-child-img';

/**
 * IFrameDocumentPostProcessor that identifies parent paragraphs of image elements
 * and decorates them with a class if their first child node is an image.
 *
 * @export
 * @param {IFrameDocumentPostProcessorParameters} parameters - processor parameters
 * @return {Promise<void>}
 */
export async function elementDecoratorPostProcessor(
  parameters: IFrameDocumentPostProcessorParameters,
): Promise<void> {
  const { document } = parameters

  if (!document) {
    throw new Error('The document should not be empty')
  }
  if (typeof document !== 'object') {
    throw new Error('The document should be an object')
  }

  processImageFirstChildParagraphs(document);

  return Promise.resolve();
}

function processImageFirstChildParagraphs(document: Document) {
  const images = document.images

  if (!images) {
    throw new Error('The collection of the document images should be defined')
  }

  for (let i = 0; i < images.length; i++) {
    let img = images[i];
    if (!img || !img.parentElement) continue;

    let parent = img.parentElement;
    if (parent.tagName !== 'P') continue;

    if (parent.firstChild === img) {
        parent.classList.add(ParagraphFirstChildImageClassname);
    }
  }
}
